['name'=>'Scalar Types','brief'=>'int, float, string, bool','explanation'=>'PHP has four scalar types: int (whole numbers), float (decimals), string (text), and bool (true/false). PHP handles type conversion automatically through type juggling.','syntax'=>'<span class="var">$age</span> <span class="op">=</span> <span class="num">25</span>;\n<span class="var">$price</span> <span class="op">=</span> <span class="num">19.99</span>;\n<span class="var">$name</span> <span class="op">=</span> <span class="str">\'John\'</span>;\n<span class="var">$active</span> <span class="op">=</span> <span class="kw">true</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$int</span> <span class="op">=</span> <span class="num">42</span>;\n<span class="var">$float</span> <span class="op">=</span> <span class="num">3.14</span>;\n<span class="var">$string</span> <span class="op">=</span> <span class="str">"PHP"</span>;\n<span class="var">$bool</span> <span class="op">=</span> <span class="kw">true</span>;\n\n<span class="kw">echo</span> <span class="fn">gettype</span>(<span class="var">$int</span>);\n<span class="kw">echo</span> <span class="fn">is_int</span>(<span class="var">$int</span>);\n<span class="kw">echo</span> <span class="fn">is_float</span>(<span class="var">$float</span>);\n<span class="kw">echo</span> <span class="fn">is_string</span>(<span class="var">$string</span>);\n<span class="kw">echo</span> <span class="fn">is_bool</span>(<span class="var">$bool</span>);','useCases'=>['Storing numbers for calculations','Representing text content','Conditional logic flags','Working with measurements'],'mistakes'=>['Comparing floats with == due to precision','Confusing string "0" with boolean false','Assuming integer overflow works like C'],['tips'=>['Use === to avoid type juggling issues','Use PHP_INT_MAX for platform integer limit','Use bcmath for arbitrary precision'],['interview'=>['What are the four scalar types?','What is type juggling?','When should you use === vs ==?']],
['name'=>'Compound Types','brief'=>'array and object','explanation'=>'Arrays hold multiple values and can be indexed, associative, or multidimensional. Objects are instances of classes combining data and behavior.','syntax'=>'<span class="var">$arr</span> <span class="op">=</span> [<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>];\n<span class="var">$assoc</span> <span class="op">=</span> [<span class="str">\'key\'</span> <span class="op">=&gt;</span> <span class="str">\'value\'</span>];\n<span class="kw">class</span> <span class="fn">User</span> {\n    <span class="kw">public</span> <span class="var">$name</span>;\n}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$colors</span> <span class="op">=</span> [<span class="str">\'red\'</span>, <span class="str">\'green\'</span>, <span class="str">\'blue\'</span>];\n<span class="fn">array_push</span>(<span class="var">$colors</span>, <span class="str">\'yellow\'</span>);\n<span class="kw">echo</span> <span class="var">$colors</span>[<span class="num">0</span>];\n<span class="kw">class</span> <span class="fn">Product</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(\n        <span class="kw">public</span> <span class="var">string</span> <span class="var">$name</span>,\n        <span class="kw">public</span> <span class="kw">float</span> <span class="var">$price</span>\n    ){}\n}\n<span class="var">$p</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">Product</span>(<span class="str">\'Laptop\'</span>, <span class="num">999.99</span>);','useCases'=>['Collections of related data','Modeling real-world entities','Configuration and settings','Encapsulating complex behavior'],'mistakes'=>['Trying to use object as array without ArrayAccess','Confusing array() with [] syntax','Not understanding objects pass by handle'],'tips'=>['Use short array syntax [] for cleaner code','Objects pass by handle - no need for &','Use stdClass for quick anonymous objects'],'interview'=>['Difference between arrays and objects?','When to use array vs object?','Can objects implement array behavior?']],
['name'=>'Special Types','brief'=>'null and resource','explanation'=>'null represents a variable with no value. Resources hold references to external things like database connections and file handles.','syntax'=>'<span class="var">$var</span> <span class="op">=</span> <span class="kw">null</span>;\n<span class="kw">echo</span> <span class="fn">is_null</span>(<span class="var">$var</span>);\n\n<span class="var">$file</span> <span class="op">=</span> <span class="fn">fopen</span>(<span class="str">\'test.txt\'</span>, <span class="str">\'r\'</span>);\n<span class="kw">echo</span> <span class="fn">gettype</span>(<span class="var">$file</span>);\n<span class="fn">fclose</span>(<span class="var">$file</span>);','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$a</span> <span class="op">=</span> <span class="kw">null</span>;\n<span class="var">$b</span>; <span class="cmt">// also null</span>\n<span class="kw">echo</span> <span class="var">$a</span> <span class="op">===</span> <span class="var">$b</span> ? <span class="str">\'Both null\'</span> : <span class="str">\'Different\'</span>;\n\n<span class="var">$conn</span> <span class="op">=</span> <span class="fn">fopen</span>(<span class="str">\'data.txt\'</span>, <span class="str">\'w\'</span>);\n<span class="kw">if</span> (<span class="var">$conn</span>) {\n    <span class="fn">fwrite</span>(<span class="var">$conn</span>, <span class="str">"Hello"</span>);\n    <span class="fn">fclose</span>(<span class="var">$conn</span>);\n}','useCases'=>['Checking if variable is initialized','Database connections (resource)','File handling operations (resource)','Detecting missing values (null)'],'mistakes'=>['Not checking resource validity before use','Forgetting to close resources','Confusing null with empty string or 0'],'tips'=>['Use === null for strict null check','Always close resources with try/finally','Use null coalescing for null defaults'],'interview'=>['Difference between null and empty string?','What are resources in PHP?','How to check if a variable is null?']],
['name'=>'Type Casting','brief'=>'Explicit and implicit conversion','explanation':'PHP automatically converts between types (type juggling), but you can explicitly cast using (int), (float), (string), (bool). The settype() function changes a variable type in place.','syntax'=>'<span class="var">$num</span> <span class="op">=</span> <span class="punct">(</span><span class="kw">int</span><span class="punct">)</span> <span class="str">"42"</span>;\n<span class="var">$float</span> <span class="op">=</span> <span class="punct">(</span><span class="kw">float</span><span class="punct">)</span> <span class="str">"3.14"</span>;\n<span class="var">$str</span> <span class="op">=</span> <span class="punct">(</span><span class="kw">string</span><span class="punct">)</span> <span class="num">100</span>;\n<span class="var">$bool</span> <span class="op">=</span> <span class="punct">(</span><span class="kw">bool</span><span class="punct">)</span> <span class="str">""</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$result</span> <span class="op">=</span> <span class="str">"5"</span> <span class="op">+</span> <span class="num">3</span>;\n<span class="kw">echo</span> <span class="var">$result</span>; <span class="cmt">// 8</span>\n<span class="var">$count</span> <span class="op">=</span> <span class="punct">(</span><span class="kw">int</span><span class="punct">)</span> <span class="num">4.9</span>;\n<span class="kw">echo</span> <span class="var">$count</span>; <span class="cmt">// 4 (truncated)</span>\n<span class="kw">echo</span> <span class="fn">intval</span>(<span class="str">"42abc"</span>);\n<span class="kw">echo</span> <span class="fn">is_numeric</span>(<span class="str">"42"</span>);','useCases'=>['Converting user input to numbers','Ensuring correct database types','Handling form data as strings','Converting between data formats'],'mistakes'=>['Assuming (int) rounds instead of truncates','Not accounting for type juggling','Forgetting empty string casts to 0'],'tips'=>['Use (int)$var or intval($var)','Validate before casting with is_numeric()','In PHP 8 use mixed for strict typing'],'interview'=>['What happens casting float to int?','What is type juggling?','How does "0" == false work?']]
]
