'subs'=>[
['name'=>'define() Function','brief'=>'Runtime constant definition','explanation'=>'define() creates a constant at runtime. Constants are immutable and typically UPPER_SNAKE_CASE. They are case-sensitive by default but configurable.','syntax'=>'<span class="fn">define</span>(<span class="str">\'APP_NAME\'</span>, <span class="str">\'MyApp\'</span>);\n<span class="fn">define</span>(<span class="str">\'MAX\'</span>, <span class="num">1024</span>, <span class="kw">true</span>);\n<span class="kw">echo</span> <span class="fn">APP_NAME</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="fn">define</span>(<span class="str">\'DB_HOST\'</span>, <span class="str">\'localhost\'</span>);\n<span class="fn">define</span>(<span class="str">\'DB_PORT\'</span>, <span class="num">3306</span>);\n<span class="fn">define</span>(<span class="str">\'APP_VERSION\'</span>, <span class="str">\'2.0\'</span>);\n<span class="fn">define</span>(<span class="str">\'PI\'</span>, <span class="num">3.14159</span>);\n\n<span class="kw">if</span> (<span class="fn">defined</span>(<span class="str">\'DB_HOST\'</span>)) {\n    <span class="kw">echo</span> <span class="fn">DB_HOST</span>;\n}\n<span class="var">$circ</span> <span class="op">=</span> <span class="num">2</span> <span class="op">*</span> <span class="fn">PI</span> <span class="op">*</span> <span class="num">5</span>;','useCases'=>['Database configuration','Application settings','Mathematical constants','Feature flags'],'mistakes'=>['Trying to redefine a constant','Using $ with constant names','Defining inside conditional blocks'],'tips'=>['Use define() for runtime constants','Group related constants in configs','Consider PHP 8.1 enums'],'interview'=>['Difference between define() and const?','Can you redefine a constant?','Why UPPER_SNAKE_CASE?']],
['name'=>'const Keyword','brief'=>'Compile-time constant declaration','explanation'=>'const defines a constant at compile time. Unlike define(), const can be used inside classes for class constants and is always case-sensitive.','syntax'=>'<span class="kw">const</span> <span class="fn">MAX_ITEMS</span> <span class="op">=</span> <span class="num">50</span>;\n<span class="kw">class</span> <span class="fn">Config</span> {\n    <span class="kw">const</span> <span class="fn">VERSION</span> <span class="op">=</span> <span class="str">\'1.0\'</span>;\n}\n<span class="kw">echo</span> <span class="fn">Config</span>::<span class="fn">VERSION</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">const</span> <span class="fn">API_URL</span> <span class="op">=</span> <span class="str">\'https://api.example.com\'</span>;\n\n<span class="kw">class</span> <span class="fn">HttpStatus</span> {\n    <span class="kw">const</span> <span class="fn">OK</span> <span class="op">=</span> <span class="num">200</span>;\n    <span class="kw">const</span> <span class="fn">NOT_FOUND</span> <span class="op">=</span> <span class="num">404</span>;\n    <span class="kw">const</span> <span class="fn">SERVER_ERROR</span> <span class="op">=</span> <span class="num">500</span>;\n\n    <span class="kw">public</span> <span class="kw">static</span> <span class="kw">function</span> <span class="fn">msg</span>(<span class="kw">int</span> <span class="var">$c</span>): <span class="var">string</span> {\n        <span class="kw">return</span> <span class="kw">match</span>(<span class="var">$c</span>) {\n            <span class="kw">self</span>::<span class="fn">OK</span> <span class="op">=&gt;</span> <span class="str">\'OK\'</span>,\n            <span class="kw">self</span>::<span class="fn">NOT_FOUND</span> <span class="op">=&gt;</span> <span class="str">\'Not Found\'</span>,\n            <span class="kw">default</span> <span class="op">=&gt;</span> <span class="str">\'Error\'</span>,\n        };\n    }\n}','useCases'=>['Class-level configuration','Status code enums','Application settings','Interface contracts'],'mistakes'=>['Using const in conditional blocks','Trying const with dynamic values','Forgetting :: to access class constants'],'tips'=>['Use const for class constants','const resolved at compile time','PHP 8.1 enums for related groups'],'interview'=>['Difference between const and define()?','Can const be in a function?','How to access class constants?']],
['name'=>'Magic Constants','brief'=>'__LINE__, __FILE__, __DIR__ etc.','explanation':'Magic constants change values based on where they are used. They start and end with double underscores. Common ones: __LINE__, __FILE__, __DIR__, __FUNCTION__, __CLASS__, __METHOD__, __NAMESPACE__.','syntax'=>'<span class="kw">echo</span> <span class="fn">__LINE__</span>;\n<span class="kw">echo</span> <span class="fn">__FILE__</span>;\n<span class="kw">echo</span> <span class="fn">__DIR__</span>;\n<span class="kw">echo</span> <span class="fn">__FUNCTION__</span>;\n<span class="kw">echo</span> <span class="fn">__CLASS__</span>;\n<span class="kw">echo</span> <span class="fn">__METHOD__</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">namespace</span> App\\\\Models;\n\n<span class="kw">echo</span> <span class="str">"File: </span><span class="fn">__FILE__</span><span class="str">&lt;br&gt;"</span>;\n<span class="kw">echo</span> <span class="str">"Dir: </span><span class="fn">__DIR__</span><span class="str">&lt;br&gt;"</span>;\n<span class="kw">echo</span> <span class="str">"Line: </span><span class="fn">__LINE__</span><span class="str">&lt;br&gt;"</span>;\n\n<span class="kw">class</span> <span class="fn">Logger</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">log</span>(<span class="var">string</span> <span class="var">$msg</span>): <span class="var">void</span> {\n        <span class="var">$file</span> <span class="op">=</span> <span class="fn">basename</span>(<span class="fn">__FILE__</span>);\n        <span class="kw">echo</span> <span class="str">"</span><span class="var">$file</span><span class="str"> </span><span class="fn">__METHOD__</span><span class="str">: </span><span class="var">$msg</span><span class="str">&lt;br&gt;"</span>;\n    }\n}','useCases'=>['Debugging with file/line info','Path resolution with __DIR__','Framework routing with __METHOD__','Namespace-aware class loading'],'mistakes'=>['Confusing __FUNCTION__ with __METHOD__','Expecting same behavior in includes','Using __TRAIT__ which is uncommon'],'tips'=>['__DIR__ essential for require paths','Use __METHOD__ for logging','__LINE__ for quick debugging'],'interview'=>['Difference between __FUNCTION__ and __METHOD__?','List 5 magic constants.','How is __DIR__ useful for autoloading?']]
]
];
