'id'=>'operators','name'=>'Operators','icon'=>'⚙️','color'=>'#14b8a6',
'subs'=>[
['name'=>'Arithmetic Operators','brief'=>'+, -, *, /, %, **','explanation'=>'Arithmetic operators perform math: addition (+), subtraction (-), multiplication (*), division (/), modulus (%), and exponentiation (**). Division by zero returns INF for floats in PHP 8+.','syntax'=>'<span class="var">$a</span> <span class="op">=</span> <span class="num">10</span>; <span class="var">$b</span> <span class="op">=</span> <span class="num">3</span>;\n<span class="var">$a</span> <span class="op">+</span> <span class="var">$b</span>;  <span class="cmt">// 13</span>\n<span class="var">$a</span> <span class="op">-</span> <span class="var">$b</span>;  <span class="cmt">// 7</span>\n<span class="var">$a</span> <span class="op">*</span> <span class="var">$b</span>;  <span class="cmt">// 30</span>\n<span class="var">$a</span> <span class="op">/</span> <span class="var">$b</span>;  <span class="cmt">// 3.333</span>\n<span class="var">$a</span> <span class="op">%</span> <span class="var">$b</span>;  <span class="cmt">// 1</span>\n<span class="var">$a</span> <span class="op">**</span> <span class="var">$b</span>; <span class="cmt">// 1000</span>','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$a</span> <span class="op">=</span> <span class="num">17</span>; <span class="var">$b</span> <span class="op">=</span> <span class="num">5</span>;\n<span class="kw">echo</span> <span class="str">"</span><span class="var">$a</span> <span class="op">+</span> <span class="var">$b</span> <span class="op">=</span> <span class="str">" . (<span class="var">$a</span> + <span class="var">$b</span>);</span>\n<span class="kw">echo</span> <span class="str">"</span><span class="var">$a</span> <span class="op">%</span> <span class="var">$b</span> <span class="op">=</span> <span class="str">" . (<span class="var">$a</span> % <span class="var">$b</span>);</span>\n<span class="kw">echo</span> <span class="fn">intdiv</span>(<span class="num">17</span>, <span class="num">5</span>);\n<span class="kw">echo</span> <span class="num">2</span> <span class="op">**</span> <span class="num">10</span>; <span class="cmt">// 1024</span>','useCases'=>['Calculating prices and taxes','Finding remainders for pagination','Exponentiation for powers','Percentage calculations'],'mistakes'=>['Integer division truncates not rounds','Division by zero errors in PHP 8','Operator precedence: 2+3*4 = 14 not 20'],'tips'=>['Use intdiv() for integer division','Be careful with float precision','Remember ** for exponentiation'],'interview'=>['What is 10 % 3?','How does PHP handle division by zero?','Difference between / and intdiv()?']],
['name'=>'Comparison Operators','brief'=>'==, ===, !=, !==, <, >, <=>','explanation'=>'Comparison operators return booleans. Loose (==) performs type juggling. Strict (===) checks value and type. Spaceship (<=>) returns -1, 0, or 1.','syntax'=>'<span class="num">0</span> <span class="op">==</span> <span class="str">"foo"</span>  <span class="cmt">// true (pre-PHP 8)</span>\n<span class="num">0</span> <span class="op">===</span> <span class="str">"foo"</span> <span class="cmt">// false (always)</span>\n<span class="num">1</span> <span class="op">&lt;=&gt;</span> <span class="num">2</span> <span class="cmt">// -1</span>\n<span class="num">2</span> <span class="op">&lt;=&gt;</span> <span class="num">2</span> <span class="cmt">// 0</span>\n<span class="num">3</span> <span class="op">&lt;=&gt;</span> <span class="num">2</span> <span class="cmt">// 1</span>','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$x</span> <span class="op">=</span> <span class="num">10</span>; <span class="var">$y</span> <span class="op">=</span> <span class="str">"10"</span>;\n<span class="kw">echo</span> <span class="var">$x</span> <span class="op">==</span> <span class="var">$y</span> ? <span class="str">\'true\'</span> : <span class="str">\'false\'</span>;\n<span class="kw">echo</span> <span class="var">$x</span> <span class="op">===</span> <span class="var">$y</span> ? <span class="str">\'true\'</span> : <span class="str">\'false\'</span>;\n\n<span class="var">$items</span> <span class="op">=</span> [<span class="num">5</span>, <span class="num">2</span>, <span class="num">8</span>, <span class="num">1</span>];\n<span class="fn">usort</span>(<span class="var">$items</span>, <span class="kw">fn</span>(<span class="var">$a</span>,<span class="var">$b</span>) <span class="op">=&gt;</span> <span class="var">$a</span> <span class="op">&lt;=&gt;</span> <span class="var">$b</span>);','useCases'=>['Validating user input types','Sorting with spaceship','Conditional logic with type safety','Checking for null values'],'mistakes'=>['Using == instead of ===','Not knowing 0 == "" was true in PHP 7','Confusing = with =='],'tips'=>['Always prefer === for predictability','Use spaceship for custom sorting','PHP 8 made 0 == "foo" false'],'interview'=>['Difference between == and ===?','How does spaceship work?','What changed in PHP 8.0 comparisons?']],
['name'=>'Logical Operators','brief'=>'&&, ||, !, and, or, xor','explanation'=>'Logical operators combine booleans. && (both true), || (either true), ! (negate). Word versions (and, or, xor) have different precedence.','syntax'=>'<span class="var">$a</span> <span class="op">=</span> <span class="kw">true</span>; <span class="var">$b</span> <span class="op">=</span> <span class="kw">false</span>;\n<span class="var">$a</span> <span class="op">&amp;&amp;</span> <span class="var">$b</span>;  <span class="cmt">// false</span>\n<span class="var">$a</span> <span class="op">||</span> <span class="var">$b</span>;  <span class="cmt">// true</span>\n<span class="op">!</span><span class="var">$a</span>;       <span class="cmt">// false</span>\n<span class="var">$a</span> <span class="op">xor</span> <span class="var">$b</span>; <span class="cmt">// true</span>','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$age</span> <span class="op">=</span> <span class="num">25</span>; <span class="var">$hasLicense</span> <span class="op">=</span> <span class="kw">true</span>;\n\n<span class="kw">if</span> (<span class="var">$age</span> <span class="op">&gt;=</span> <span class="num">18</span> <span class="op">&amp;&amp;</span> <span class="var">$hasLicense</span>) {\n    <span class="kw">echo</span> <span class="str">"Can drive&lt;br&gt;"</span>;\n}\n<span class="kw">if</span> (<span class="var">$hasLicense</span> <span class="op">||</span> <span class="var">$hasInsurance</span>) {\n    <span class="kw">echo</span> <span class="str">"Has coverage&lt;br&gt;"</span>;\n}\n<span class="kw">if</span> (<span class="op">!</span><span class="var">$hasInsurance</span>) {\n    <span class="kw">echo</span> <span class="str">"Needs insurance&lt;br&gt;"</span>;\n}','useCases'=>['Combining multiple conditions','Validating multiple form fields','Complex filter expressions','Permission checks'],'mistakes'=>['Confusing && with and (precedence)','Using || vs or (precedence)','Not understanding short-circuiting'],'tips'=>['Use && and || symbol versions','&& and || short-circuit','Use xor for exactly one true'],'interview'=>['Difference between && and and?','What is short-circuit evaluation?','Precedence of && vs and?']],
['name'=>'Assignment Operators','brief'=>'=, +=, -=, .=, etc.','explanation'=>'Assignment operators assign values. Compound operators combine math with assignment: +=, -=, *=, /=, %=, .=, **=.','syntax'=>'<span class="var">$a</span> <span class="op">=</span> <span class="num">10</span>;\n<span class="var">$a</span> <span class="op">+=</span> <span class="num">5</span>;  <span class="cmt">// 15</span>\n<span class="var">$a</span> <span class="op">-=</span> <span class="num">3</span>;  <span class="cmt">// 12</span>\n<span class="var">$a</span> <span class="op">*=</span> <span class="num">2</span>;  <span class="cmt">// 24</span>\n<span class="var">$a</span> <span class="op">**=</span> <span class="num">3</span>; <span class="cmt">// 8</span>\n<span class="var">$str</span> <span class="op">.=</span> <span class="str">"!"</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$count</span> <span class="op">=</span> <span class="num">0</span>;\n<span class="var">$count</span> <span class="op">+=</span> <span class="num">1</span>;\n<span class="var">$count</span> <span class="op">+=</span> <span class="num">5</span>;\n<span class="var">$count</span> <span class="op">-=</span> <span class="num">2</span>;\n<span class="kw">echo</span> <span class="var">$count</span>; <span class="cmt">// 4</span>\n\n<span class="var">$greeting</span> <span class="op">=</span> <span class="str">"Hello"</span>;\n<span class="var">$greeting</span> <span class="op">.=</span> <span class="str">" World"</span>;\n<span class="var">$greeting</span> <span class="op">.=</span> <span class="str">"!"</span>;\n<span class="kw">echo</span> <span class="var">$greeting</span>; <span class="cmt">// Hello World!</span>','useCases'=>['Accumulating totals in loops','Building strings incrementally','Updating counters','Running calculations'],'mistakes'=>['Using = instead of == in conditions','Confusing . with +','Not realizing .= works with strings'],'tips'=>['Use .= for string concatenation','Compound assignments are more readable','$a = $b = $c = 0 right to left'],'interview'=>['Difference between = and ==?','List compound assignment operators.','What does .= do?']],
['name'=>'Special Operators','brief'=>'??, <=>, ?:, instanceof','explanation'=>'Null coalescing (??) returns left if not null. Spaceship (<=>) returns -1/0/1. Ternary (? :) is inline if-else. instanceof checks object type.','syntax'=>'<span class="var">$name</span> <span class="op">=</span> <span class="var">$_GET</span>[<span class="str">\'n\'</span>] <span class="op">??</span> <span class="str">\'Guest\'</span>;\n<span class="var">$c</span>[<span class="str">\'t\'</span>] <span class="op">??=</span> <span class="num">30</span>;\n<span class="var">$s</span> <span class="op">=</span> <span class="var">$age</span> <span class="op">&gt;=</span> <span class="num">18</span> <span class="op">?</span> <span class="str">\'adult\'</span> <span class="op">:</span> <span class="str">\'minor\'</span>;\n<span class="num">1</span> <span class="op">&lt;=&gt;</span> <span class="num">2</span>; <span class="cmt">// -1</span>\n<span class="var">$o</span> <span class="kw">instanceof</span> <span class="fn">User</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$name</span> <span class="op">=</span> <span class="var">$_POST</span>[<span class="str">\'n\'</span>] <span class="op">??</span> <span class="var">$_GET</span>[<span class="str">\'n\'</span>] <span class="op">??</span> <span class="str">\'Guest\'</span>;\n<span class="kw">echo</span> <span class="str">"Hello, </span><span class="var">$name</span><span class="str">&lt;br&gt;"</span>;\n\n<span class="var">$hour</span> <span class="op">=</span> <span class="num">14</span>;\n<span class="var">$g</span> <span class="op">=</span> <span class="var">$hour</span> <span class="op">&lt;</span> <span class="num">12</span>\n    <span class="op">?</span> <span class="str">"Good morning"</span>\n    <span class="op">:</span> (<span class="var">$hour</span> <span class="op">&lt;</span> <span class="num">18</span> <span class="op">?</span> <span class="str">"Good afternoon"</span> <span class="op">:</span> <span class="str">"Good evening"</span>);\n\n<span class="var">$users</span> <span class="op">=</span> [\n    [<span class="str">\'name\'</span><span class="op">=&gt;</span><span class="str">\'C\'</span>,<span class="str">\'age\'</span><span class="op">=&gt;</span><span class="num">30</span>],\n    [<span class="str">\'name\'</span><span class="op">=&gt;</span><span class="str">\'A\'</span>,<span class="str">\'age\'</span><span class="op">=&gt;</span><span class="num">25</span>],\n];\n<span class="fn">usort</span>(<span class="var">$users</span>, <span class="kw">fn</span>(<span class="var">$a</span>,<span class="var">$b</span>) <span class="op">=&gt;</span> <span class="var">$a</span>[<span class="str">\'age\'</span>] <span class="op">&lt;=&gt;</span> <span class="var">$b</span>[<span class="str">\'age\'</span>]);','useCases'=>['Safe null value access (??)','Custom sorting (<=>)','Inline conditions (ternary)','Type checking (instanceof)'],'mistakes'=>['Nesting ternary without parentheses','Using ?? when you mean ||','Not knowing ?? only checks null'],'tips'=>['Use ?? instead of isset() ternary','Chain ?? for fallback values','Use instanceof for type checking'],'interview'=>['Difference between ?? and ||?','How does spaceship work?','When to use instanceof?']]
]
