$topics[] = [
'id'=>'conditions','name'=>'Conditions','icon'=>'🔀','color'=>'#f59e0b',
'subs'=>[
['name'=>'If/Else/ElseIf','brief'=>'Conditional branching','explanation'=>'Executes code blocks based on boolean conditions. Evaluated top-down; the first true block runs. else handles the default case.','syntax'=>'<span class="kw">if</span> (<span class="var">$c1</span>) {\n    <span class="cmt">// true</span>\n} <span class="kw">elseif</span> (<span class="var">$c2</span>) {\n    <span class="cmt">// c1 false, c2 true</span>\n} <span class="kw">else</span> {\n    <span class="cmt">// all false</span>\n}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$score</span> <span class="op">=</span> <span class="num">85</span>;\n<span class="kw">if</span> (<span class="var">$score</span> <span class="op">&gt;=</span> <span class="num">90</span>) {\n    <span class="var">$grade</span> <span class="op">=</span> <span class="str">\'A\'</span>;\n} <span class="kw">elseif</span> (<span class="var">$score</span> <span class="op">&gt;=</span> <span class="num">80</span>) {\n    <span class="var">$grade</span> <span class="op">=</span> <span class="str">\'B\'</span>;\n} <span class="kw">elseif</span> (<span class="var">$score</span> <span class="op">&gt;=</span> <span class="num">70</span>) {\n    <span class="var">$grade</span> <span class="op">=</span> <span class="str">\'C\'</span>;\n} <span class="kw">else</span> {\n    <span class="var">$grade</span> <span class="op">=</span> <span class="str">\'F\'</span>;\n}\n<span class="kw">echo</span> <span class="str">"Score: </span><span class="var">$score</span><span class="str">, Grade: </span><span class="var">$grade</span><span class="str">"</span>;','useCases'=>['Grading systems','Access control and permissions','Form validation feedback','Feature toggling'],'mistakes'=>['Using = instead of == in conditions','Forgetting curly braces','Not handling else case'],'tips'=>['Use early returns to reduce nesting','Consider match for multiple equal values','Use === for type-safe conditions'],'interview'=>['elseif vs else if?','How to avoid deep nesting?','Can if have multiple expressions?']],
['name'=>'Switch Statement','brief'=>'Multi-branch selection','explanation'=>'Compares a single expression against multiple cases using loose comparison (==). break prevents fall-through. default handles unmatched values.','syntax'=>'<span class="kw">switch</span> (<span class="var">$val</span>) {\n    <span class="kw">case</span> <span class="str">\'a\'</span>:\n        <span class="cmt">// code</span>\n        <span class="kw">break</span>;\n    <span class="kw">case</span> <span class="str">\'b\'</span>:\n        <span class="cmt">// code</span>\n        <span class="kw">break</span>;\n    <span class="kw">default</span>:\n        <span class="cmt">// default</span>\n        <span class="kw">break</span>;\n}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$method</span> <span class="op">=</span> <span class="var">$_SERVER</span>[<span class="str">\'REQUEST_METHOD\'</span>];\n<span class="kw">switch</span> (<span class="var">$method</span>) {\n    <span class="kw">case</span> <span class="str">\'GET\'</span>:\n        <span class="kw">echo</span> <span class="str">"Displaying form"</span>;\n        <span class="kw">break</span>;\n    <span class="kw">case</span> <span class="str">\'POST\'</span>:\n        <span class="kw">echo</span> <span class="str">"Processing form"</span>;\n        <span class="kw">break</span>;\n    <span class="kw">default</span>:\n        <span class="kw">echo</span> <span class="str">"Method not allowed"</span>;\n        <span class="kw">break</span>;\n}\n\n<span class="cmt">// Fall-through for grouping</span>\n<span class="kw">switch</span> (<span class="var">$month</span>) {\n    <span class="kw">case</span> <span class="num">12</span>: <span class="kw">case</span> <span class="num">1</span>: <span class="kw">case</span> <span class="num">2</span>:\n        <span class="kw">echo</span> <span class="str">"Winter"</span>;\n        <span class="kw">break</span>;\n    <span class="kw">case</span> <span class="num">3</span>: <span class="kw">case</span> <span class="num">4</span>: <span class="kw">case</span> <span class="num">5</span>:\n        <span class="kw">echo</span> <span class="str">"Spring"</span>;\n        <span class="kw">break</span>;\n}','useCases'=>['Routing HTTP methods','Menu navigation','Processing enum values','Day/month conversions'],'mistakes'=>['Forgetting break causes fall-through','Using switch with arrays','Not providing default case'],'tips'=>['Consider match (PHP 8) over switch','Use fall-through intentionally','Always include default case'],'interview'=>['switch vs match?','What happens without break?','How does switch compare values?']],
['name'=>'Match Expression','brief'=>'PHP 8.0+ strict matching','explanation':'Modern alternative to switch using strict comparison (===). Returns values, no break needed, supports pipe (|). Throws UnhandledMatchError if no match.','syntax'=>'<span class="var">$r</span> <span class="op">=</span> <span class="kw">match</span> (<span class="var">$code</span>) {\n    <span class="num">200</span>, <span class="num">201</span> <span class="op">=&gt;</span> <span class="str">\'Success\'</span>,\n    <span class="num">404</span> <span class="op">=&gt;</span> <span class="str">\'Not Found\'</span>,\n    <span class="kw">default</span> <span class="op">=&gt;</span> <span class="str">\'Unknown\'</span>,\n};','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$dow</span> <span class="op">=</span> <span class="fn">date</span>(<span class="str">\'w\'</span>);\n<span class="var">$type</span> <span class="op">=</span> <span class="kw">match</span>(<span class="var">$dow</span>) {\n    <span class="num">0</span> <span class="op">=&gt;</span> <span class="str">\'Sunday\'</span>,\n    <span class="num">6</span> <span class="op">=&gt;</span> <span class="str">\'Saturday\'</span>,\n    <span class="kw">default</span> <span class="op">=&gt;</span> <span class="str">\'Weekday\'</span>,\n};\n\n<span class="cmt">// Pipe for multiple conditions</span>\n<span class="var">$season</span> <span class="op">=</span> <span class="kw">match</span>(<span class="var">$month</span>) {\n    <span class="num">12</span>, <span class="num">1</span>, <span class="num">2</span> <span class="op">=&gt;</span> <span class="str">\'Winter\'</span>,\n    <span class="num">3</span>, <span class="num">4</span>, <span class="num">5</span> <span class="op">=&gt;</span> <span class="str">\'Spring\'</span>,\n    <span class="num">6</span>, <span class="num">7</span>, <span class="num">8</span> <span class="op">=&gt;</span> <span class="str">\'Summer\'</span>,\n    <span class="num">9</span>, <span class="num">10</span>, <span class="num">11</span> <span class="op">=&gt;</span> <span class="str">\'Fall\'</span>,\n};','useCases'=>['Returning values based on conditions','Replacing verbose switch','Type-safe value mapping','Enum-like resolution'],'mistakes'=>['Expecting loose comparison','Not handling all values (throws error)','Forgetting match is an expression'],'tips'=>['Prefer match over switch in PHP 8+','Use pipe (|) for multiple values','Match is faster with strict comparison'],'interview'=>['match vs switch?','Why strict comparison?','What if no case matches?']],
['name'=>'Ternary Operator','brief'=>'Inline if-else','explanation'=>'Shorthand for if-else: condition ? true_val : false_val. Elvis operator ?: checks truthy values. Keep it simple for readability.','syntax'=>'<span class="var">$r</span> <span class="op">=</span> <span class="var">$cond</span> <span class="op">?</span> <span class="str">\'yes\'</span> <span class="op">:</span> <span class="str">\'no\'</span>;\n<span class="cmt">// Elvis</span>\n<span class="var">$n</span> <span class="op">=</span> <span class="var">$input</span> <span class="op">?:</span> <span class="str">\'Unknown\'</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$age</span> <span class="op">=</span> <span class="num">20</span>;\n<span class="var">$status</span> <span class="op">=</span> <span class="var">$age</span> <span class="op">&gt;=</span> <span class="num">18</span> <span class="op">?</span> <span class="str">\'Adult\'</span> <span class="op">:</span> <span class="str">\'Minor\'</span>;\n<span class="kw">echo</span> <span class="var">$status</span>; <span class="cmt">// Adult</span>\n\n<span class="var">$ui</span> <span class="op">=</span> <span class="str">\'\'</span>;\n<span class="var">$d</span> <span class="op">=</span> <span class="var">$ui</span> <span class="op">?:</span> <span class="str">\'No input\'</span>;\n<span class="kw">echo</span> <span class="var">$d</span>; <span class="cmt">// No input</span>\n\n<span class="var">$class</span> <span class="op">=</span> <span class="var">$active</span> <span class="op">?</span> <span class="str">\'active\'</span> <span class="op">:</span> <span class="str">\'inactive\'</span>;\n<span class="kw">echo</span> <span class="str">"&lt;div class=\"</span><span class="var">$class</span><span class="str\">\"&gt;Content&lt;/div&gt;"</span>;','useCases'=>['Simple conditional assignments','Default value fallbacks','Inline conditional HTML classes','Quick boolean-to-value conversion'],'mistakes'=>['Nesting ternary operators','Using for complex logic','Confusing ?: with ??'],'tips'=>['Use ?? for null checks - cleaner','Keep ternary single-level','Use parentheses for clarity'],'interview'=>['?: vs ?? difference?','When to avoid ternary?','What does Elvis do?']],
['name'=>'Null Coalescing','brief'=>'?? and ??= operators','explanation'=>'?? returns left operand if not null, otherwise right. ??= assigns only if variable is null. Much cleaner than isset() ternary.','syntax'=>'<span class="var">$n</span> <span class="op">=</span> <span class="var">$_GET</span>[<span class="str">\'n\'</span>] <span class="op">??</span> <span class="str">\'Guest\'</span>;\n<span class="cmt">// Chain</span>\n<span class="var">$v</span> <span class="op">=</span> <span class="var">$a</span> <span class="op">??</span> <span class="var">$b</span> <span class="op">??</span> <span class="var">$c</span> <span class="op">??</span> <span class="str">\'default\'</span>;\n<span class="cmt">// Assignment</span>\n<span class="var">$cfg</span>[<span class="str">\'t\'</span>] <span class="op">??=</span> <span class="num">30</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Before PHP 7 (verbose)</span>\n<span class="var">$n</span> <span class="op">=</span> <span class="fn">isset</span>(<span class="var">$_GET</span>[<span class="str">\'name\'</span>])\n    <span class="op">?</span> <span class="var">$_GET</span>[<span class="str">\'name\'</span>]\n    <span class="op">:</span> <span class="str">\'Guest\'</span>;\n<span class="cmt">// PHP 7+ (clean)</span>\n<span class="var">$n</span> <span class="op">=</span> <span class="var">$_GET</span>[<span class="str">\'name\'</span>] <span class="op">??</span> <span class="str">\'Guest\'</span>;\n\n<span class="var">$h</span> <span class="op">=</span> <span class="var">$_ENV</span>[<span class="str">\'DB_HOST\'</span>]\n    <span class="op">??</span> <span class="var">$_SERVER</span>[<span class="str">\'DB_HOST\'</span>]\n    <span class="op">??</span> <span class="str">\'localhost\'</span>;\n\n<span class="var">$s</span> <span class="op">=</span> [];\n<span class="var">$s</span>[<span class="str">\'theme\'</span>] <span class="op">??=</span> <span class="str">\'dark\'</span>;\n<span class="var">$s</span>[<span class="str">\'lang\'</span>] <span class="op">??=</span> <span class="str">\'en\'</span>;\n<span class="fn">print_r</span>(<span class="var">$s</span>);','useCases'=>['Safe GET/POST access','Default configuration values','Chaining multiple fallbacks','Nullable parameter defaults'],'mistakes'=>['Confusing ?? with ??','Using ?? when value could be false','Not understanding it skips isset warnings'],['tips'=>['Use ?? for all null-safe access','Chain ?? for multiple fallbacks','Combine with type declarations'],'interview'=>['?? vs ?: difference?','How does ??= work?','When was ?? introduced?']]
]
