'id'=>'loops','name'=>'Loops','icon'=>'🔄','color'=>'#22c55e',
'subs'=>[
['name'=>'While Loop','brief'=>'Repeat while condition is true','explanation'=>'Executes code as long as the condition is true. Condition checked before each iteration. May not execute at all if initially false. Ideal when iterations are unknown.','syntax'=>'<span class="kw">while</span> (<span class="var">$cond</span>) {\n    <span class="cmt">// code</span>\n    <span class="cmt">// update condition</span>\n}\n<span class="cmt">// Alternative syntax</span>\n<span class="kw">while</span> (<span class="var">$cond</span>):\n    <span class="cmt">// code</span>\n<span class="kw">endwhile</span>;','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$count</span> <span class="op">=</span> <span class="num">5</span>;\n<span class="kw">while</span> (<span class="var">$count</span> <span class="op">&gt;</span> <span class="num">0</span>) {\n    <span class="kw">echo</span> <span class="str">"</span><span class="var">$count</span><span class="str">...&lt;br&gt;"</span>;\n    <span class="var">$count</span>--;\n}\n<span class="kw">echo</span> <span class="str">"Go!"</span>;\n\n<span class="cmt">// File reading</span>\n<span class="var">$h</span> <span class="op">=</span> <span class="fn">fopen</span>(<span class="str">\'data.txt\'</span>, <span class="str">\'r\'</span>);\n<span class="kw">while</span> (<span class="op">!</span><span class="fn">feof</span>(<span class="var">$h</span>)) {\n    <span class="var">$line</span> <span class="op">=</span> <span class="fn">fgets</span>(<span class="var">$h</span>);\n    <span class="kw">echo</span> <span class="var">$line</span>;\n}\n<span class="fn">fclose</span>(<span class="var">$h</span>);','useCases'=>['Reading files until EOF','Processing database results','Input validation loops','Countdown logic'],'mistakes'=>['Infinite loop when condition never false','Not updating condition variable','Using while when for is clearer'],'tips'=>['Ensure condition becomes false','Use safety counter for dev','Consider break and continue'],['interview'=>['When use while vs for?','How to prevent infinite loops?','while vs do-while?']],
['name'=>'Do-While Loop','brief'=>'Execute at least once','explanation':'Checks condition after executing the code block. Guarantees at least one execution. Useful when you need to run code once then repeat.','syntax'=>'<span class="kw">do</span> {\n    <span class="cmt">// code (runs at least once)</span>\n} <span class="kw">while</span> (<span class="var">$cond</span>);\n<span class="cmt">// Note: semicolon after while!</span>','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">do</span> {\n    <span class="kw">echo</span> <span class="str">"1. View&lt;br&gt;"</span>;\n    <span class="kw">echo</span> <span class="str">"2. Edit&lt;br&gt;"</span>;\n    <span class="kw">echo</span> <span class="str">"3. Exit&lt;br&gt;"</span>;\n    <span class="var">$choice</span> <span class="op">=</span> <span class="fn">readline</span>(<span class="str">"Choice: "</span>);\n} <span class="kw">while</span> (<span class="var">$choice</span> <span class="op">!=</span> <span class="num">3</span>);\n\n<span class="var">$attempts</span> <span class="op">=</span> <span class="num">0</span>;\n<span class="kw">do</span> {\n    <span class="var">$num</span> <span class="op">=</span> <span class="fn">rand</span>(<span class="num">1</span>, <span class="num">10</span>);\n    <span class="var">$attempts</span>++;\n    <span class="kw">echo</span> <span class="str">"Rolled: </span><span class="var">$num</span><span class="str">&lt;br&gt;"</span>;\n} <span class="kw">while</span> (<span class="var">$num</span> <span class="op">!=</span> <span class="num">6</span>);','useCases'=>['Menu-driven programs','Input validation (at least one try)','Game loops','Retry logic'],'mistakes'=>['Forgetting semicolon after while','Using when body should not execute','Not ensuring termination'],'tips'=>['Use do-while for guaranteed execution','Great for input validation','Remember the semicolon!'],'interview'=>['when use do-while?','What guarantees?','Common use case?']],
['name'=>'For Loop','brief'=>'Counted iteration','explanation':'Ideal when you know exact iterations. Three expressions: init, condition, increment. All optional. Most common loop for indexed iteration.','syntax'=>'<span class="kw">for</span> (<span class="var">$i</span> <span class="op">=</span> <span class="num">0</span>; <span class="var">$i</span> <span class="op">&lt;</span> <span class="num">10</span>; <span class="var">$i</span>++) {\n    <span class="kw">echo</span> <span class="var">$i</span>;\n}\n<span class="cmt">// Decrementing</span>\n<span class="kw">for</span> (<span class="var">$i</span> <span class="op">=</span> <span class="num">10</span>; <span class="var">$i</span> <span class="op">&gt;=</span> <span class="num">0</span>; <span class="var">$i</span>--) {}\n<span class="cmt">// Multi-variable</span>\n<span class="kw">for</span> (<span class="var">$i</span><span class="op">=</span><span class="num">0</span>, <span class="var">$j</span><span class="op">=</span><span class="num">10</span>; <span class="var">$i</span><span class="op">&lt;</span><span class="var">$j</span>; <span class="var">$i</span><span class="op">++</span>, <span class="var">$j</span><span class="op">--</span>) {}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Multiplication table</span>\n<span class="kw">for</span> (<span class="var">$i</span> <span class="op">=</span> <span class="num">1</span>; <span class="var">$i</span> <span class="op">&lt;=</span> <span class="num">10</span>; <span class="var">$i</span>++) {\n    <span class="kw">echo</span> <span class="str">"5 x </span><span class="var">$i</span><span class="str"> = </span><span class="op">{</span><span class="num">5</span> <span class="op">*</span> <span class="var">$i</span><span class="op">}</span><span class="str">&lt;br&gt;"</span>;\n}\n\n<span class="var">$colors</span> <span class="op">=</span> [<span class="str">\'red\'</span>, <span class="str">\'green\'</span>, <span class="str">\'blue\'</span>];\n<span class="kw">for</span> (<span class="var">$i</span> <span class="op">=</span> <span class="num">0</span>; <span class="var">$i</span> <span class="op">&lt;</span> <span class="fn">count</span>(<span class="var">$colors</span>); <span class="var">$i</span>++) {\n    <span class="kw">echo</span> <span class="str">"</span><span class="var">$i</span><span class="str">: </span><span class="var">$colors[$i]</span><span class="str">&lt;br&gt;"</span>;\n}\n\n<span class="cmt">// Nested loops</span>\n<span class="kw">for</span> (<span class="var">$i</span> <span class="op">=</span> <span class="num">1</span>; <span class="var">$i</span> <span class="op">&lt;=</span> <span class="num">3</span>; <span class="var">$i</span>++) {\n    <span class="kw">for</span> (<span class="var">$j</span> <span class="op">=</span> <span class="num">1</span>; <span class="var">$j</span> <span class="op">&lt;=</span> <span class="num">3</span>; <span class="var">$j</span>++) {\n        <span class="kw">echo</span> <span class="str">"</span><span class="op">{</span><span class="var">$i</span><span class="op">}</span><span class="str">×</span><span class="op">{</span><span class="var">$j</span><span class="op">}</span><span class="str">=</span><span class="op">{</span><span class="var">$i</span><span class="op">*</span><span class="var">$j</span><span class="op">}</span><span class="str> ";</span>;\n    }\n    <span class="kw">echo</span> <span class="str">"&lt;br&gt;"</span>;\n}','useCases'=>['Known iteration count','Array processing by index','Multiplication tables','Nested grid iteration'],'mistakes'=>['Off-by-one errors (< vs <=)','Modifying loop variable inside','Global scope issues with $i'],'tips'=>['Cache count() for large arrays','Use foreach for arrays','Use step: $i += 2'],'interview'=>['For loop syntax?','for vs foreach?','Iterating backwards?']],
['name'=>'Foreach Loop','brief'=>'Iterate arrays and objects','explanation':'Designed for arrays. Access each element by value or reference. Most common and cleanest way to loop through arrays. Works with Traversable objects.','syntax'=>'<span class="cmt">// By value</span>\n<span class="kw">foreach</span> (<span class="var">$arr</span> <span class="kw">as</span> <span class="var">$val</span>) {\n    <span class="kw">echo</span> <span class="var">$val</span>;\n}\n<span class="cmt">// By key => value</span>\n<span class="kw">foreach</span> (<span class="var">$arr</span> <span class="kw">as</span> <span class="var">$key</span> <span class="op">=&gt;</span> <span class="var">$val</span>) {\n    <span class="kw">echo</span> <span class="str">"</span><span class="var">$key</span><span class="str">: </span><span class="var">$val</span><span class="str">"</span>;\n}\n<span class="cmt">// By reference</span>\n<span class="kw">foreach</span> (<span class="var">$arr</span> <span class="kw">as</span> <span class="op">&</span><span class="var">$val</span>) {\n    <span class="var">$val</span> <span class="op">*=</span> <span class="num">2</span>;\n}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$fruits</span> <span class="op">=</span> [<span class="str">\'apple\'</span>, <span class="str">\'banana\'</span>, <span class="str">\'cherry\'</span>];\n<span class="kw">foreach</span> (<span class="var">$fruits</span> <span class="kw">as</span> <span class="var">$fruit</span>) {\n    <span class="kw">echo</span> <span class="var">$fruit</span> . <span class="str">"&lt;br&gt;"</span>;\n}\n\n<span class="var">$scores</span> <span class="op">=</span> [<span class="str">\'Alice\'</span><span class="op">=&gt;</span><span class="num">95</span>, <span class="str">\'Bob\'</span><span class="op">=&gt;</span><span class="num">87</span>];\n<span class="kw">foreach</span> (<span class="var">$scores</span> <span class="kw">as</span> <span class="var">$name</span> <span class="op">=&gt;</span> <span class="var">$score</span>) {\n    <span class="kw">echo</span> <span class="str">"</span><span class="var">$name</span><span class="str">: </span><span class="var">$score</span><span class="str">&lt;br&gt;"</span>;\n}\n\n<span class="cmt">// Modify by reference</span>\n<span class="var">$nums</span> <span class="op">=</span> [<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>, <span class="num">4</span>];\n<span class="kw">foreach</span> (<span class="var">$nums</span> <span class="kw">as</span> <span class="op">&</span><span class="var">$num</span>) {\n    <span class="var">$num</span> <span class="op">*=</span> <span class="num">10</span>;\n}\n<span class="fn">print_r</span>(<span class="var">$nums</span>);\n<span class="cmt">// [10, 20, 30, 40]</span>','useCases'=>['Iterating arrays','Displaying key-value pairs','Modifying elements in place','Processing database results'],'mistakes'=>['Using &$val without unsetting after','Trying to modify $key by reference','Using when you need index'],['tips'=>['Unset &$var after foreach','Use array_keys() for only keys','Foreach is faster than for'],['interview'=>['How to modify elements in foreach?','What happens with &$val?','foreach vs for for arrays?']],
['name'=>'Loop Control','brief'=>'break, continue, return','explanation':'break exits the loop. continue skips to next iteration. return exits the function. Both accept a numeric argument for nested loops.','syntax'=>'<span class="kw">for</span> (<span class="var">$i</span><span class="op">=</span><span class="num">0</span>; <span class="var">$i</span><span class="op">&lt;</span><span class="num">10</span>; <span class="var">$i</span>++) {\n    <span class="kw">if</span> (<span class="var">$i</span> <span class="op">==</span> <span class="num">3</span>) <span class="kw">continue</span>;\n    <span class="kw">if</span> (<span class="var">$i</span> <span class="op">==</span> <span class="num">7</span>) <span class="kw">break</span>;\n    <span class="kw">echo</span> <span class="var">$i</span>;\n}\n<span class="cmt">// break 2 exits two levels</span>','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Skip even numbers</span>\n<span class="kw">for</span> (<span class="var">$i</span> <span class="op">=</span> <span class="num">1</span>; <span class="var">$i</span> <span class="op">&lt;=</span> <span class="num">10</span>; <span class="var">$i</span>++) {\n    <span class="kw">if</span> (<span class="var">$i</span> <span class="op">%</span> <span class="num">2</span> <span class="op">==</span> <span class="num">0</span>) <span class="kw">continue</span>;\n    <span class="kw">echo</span> <span class="var">$i</span> . <span class="str">" "</span>;\n}\n<span class="cmt">// 1 3 5 7 9</span>\n\n<span class="cmt">// Search and break</span>\n<span class="var">$users</span> <span class="op">=</span> [<span class="str">\'Alice\'</span>, <span class="str">\'Bob\'</span>, <span class="str">\'Charlie\'</span>];\n<span class="var">$found</span> <span class="op">=</span> <span class="kw">null</span>;\n<span class="kw">foreach</span> (<span class="var">$users</span> <span class="kw">as</span> <span class="var">$user</span>) {\n    <span class="kw">if</span> (<span class="var">$user</span> <span class="op">==</span> <span class="str">\'Bob\'</span>) {\n        <span class="var">$found</span> <span class="op">=</span> <span class="var">$user</span>;\n        <span class="kw">break</span>;\n    }\n}\n<span class="kw">echo</span> <span class="var">$found</span>; <span class="cmt">// Bob</span>','useCases'=>['Skipping iterations','Early termination on match','Exiting nested loops with break N','Efficient searches'],['mistakes'=>['Using break when you mean continue','Breaking wrong loop level','Return exits function not loop'],['tips'=>['break exits, continue skips','break N exits N levels','return exits function from loop'],['interview'=>['break vs continue?','Breaking nested loops?','What does break 2 do?']]
]
