['name'=>'Indexed Array','brief'=>'Numeric indexed collections','explanation':'Indexed arrays use numeric keys starting from 0. Created with array() or []. Elements accessed by numeric index.','syntax'=>'<span class="var">$colors</span> <span class="op">=</span> [<span class="str">\'red\'</span>, <span class="str">\'green\'</span>, <span class="str">\'blue\'</span>];\n<span class="kw">echo</span> <span class="var">$colors</span>[<span class="num">0</span>]; <span class="cmt">// red</span>\n<span class="var">$colors</span>[] <span class="op">=</span> <span class="str">\'yellow\'</span>;', 'codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$fruits</span> <span class="op">=</span> [<span class="str">\'Apple\'</span>, <span class="str">\'Banana\'</span>, <span class="str">\'Cherry\'</span>];\n<span class="kw">echo</span> <span class="var">$fruits</span>[<span class="num">0</span>]; <span class="cmt">// Apple</span>\n<span class="kw">echo</span> <span class="fn">count</span>(<span class="var">$fruits</span>); <span class="cmt">// 3</span>\n\n<span class="var">$fruits</span>[] <span class="op">=</span> <span class="str">\'Date\'</span>;\n<span class="var">$fruits</span>[] <span class="op">=</span> <span class="str">\'Elderberry\'</span>;\n\n<span class="kw">foreach</span> (<span class="var">$fruits</span> <span class="kw">as</span> <span class="var">$i</span> <span class="op">=&gt;</span> <span class="var">$f</span>) {\n    <span class="kw">echo</span> <span class="str">"</span><span class="var">$i</span><span class="str">: </span><span class="var">$f</span><span class="str">&lt;br&gt;"</span>;\n}\n\n<span class="kw">unset</span>(<span class="var">$fruits</span>[<span class="num">1</span>]);\n<span class="var">$fruits</span> <span class="op">=</span> <span class="fn">array_values</span>(<span class="var">$fruits</span>);\n<span class="cmt">// Re-index</span>','useCases'=>['Storing lists of items','Processing collections','Stack and queue operations','Temporary data storage'],'mistakes'=>['Accessing non-existent index','Using count() in loop condition','unset leaves gaps in keys'],'tips'=>['Use [] short syntax','Cache count() for performance','array_values() to reindex'],'interview'=>['How to create indexed arrays?','What does unset do to keys?','How to reindex an array?']],
['name'=>'Associative Array','brief'=>'Key-value pair collections','explanation':'Uses named string keys. Perfect for structured data like database rows, configuration, or JSON structures. Keys must be unique.','syntax'=>'<span class="var">$person</span> <span class="op">=</span> [\n    <span class="str">\'name\'</span> <span class="op">=&gt;</span> <span class="str">\'John\'</span>,\n    <span class="str">\'age\'</span> <span class="op">=&gt;</span> <span class="num">25</span>,\n];\n<span class="kw">echo</span> <span class="var">$person</span>[<span class="str">\'name\'</span>];','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$user</span> <span class="op">=</span> [\n    <span class="str">\'name\'</span> <span class="op">=&gt;</span> <span class="str">\'Alice\'</span>,\n    <span class="str">\'email\'</span> <span class="op">=&gt;</span> <span class="str">\'alice@mail.com\'</span>,\n    <span class="str">\'role\'</span> <span class="op">=&gt;</span> <span class="str">\'admin\'</span>,\n];\n<span class="kw">echo</span> <span class="var">$user</span>[<span class="str">\'name\'</span>];\n\n<span class="kw">if</span> (<span class="fn">array_key_exists</span>(<span class="str">\'email\'</span>, <span class="var">$user</span>)) {\n    <span class="kw">echo</span> <span class="var">$user</span>[<span class="str">\'email\'</span>];\n}\n\n<span class="var">$keys</span> <span class="op">=</span> <span class="fn">array_keys</span>(<span class="var">$user</span>);\n<span class="var">$vals</span> <span class="op">=</span> <span class="fn">array_values</span>(<span class="var">$user</span>);','useCases'=>['Representing database rows','Configuration settings','JSON data structures','Form data processing'],'mistakes'=>['Accessing non-existent key without check','isset vs array_key_exists differences','Not quoting special character keys'],['tips'=>['Use isset() to check key existence','array_key_exists() when values can be null','null coalescing for safe access'],'interview'=>['How to check key exists?','isset vs array_key_exists?','How to get all keys/values?']],
['name'=>'Multidimensional Arrays','brief'=>'Arrays within arrays','explanation':'Contains other arrays creating nested structures. Essential for tables, matrices, or hierarchical data. Avoid deep nesting for readability.','syntax'=>'<span class="var">$matrix</span> <span class="op">=</span> [\n    [<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>],\n    [<span class="num">4</span>, <span class="num">5</span>, <span class="num">6</span>],\n];\n<span class="kw">echo</span> <span class="var">$matrix</span>[<span class="num">1</span>][<span class="num">2</span>]; <span class="cmt">// 6</span>\n\n<span class="var">$users</span> <span class="op">=</span> [\n    [<span class="str">\'name\'</span> <span class="op">=&gt;</span> <span class="str">\'John\'</span>, <span class="str">\'age\'</span> <span class="op">=&gt;</span> <span class="num">25</span>],\n];','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$students</span> <span class="op">=</span> [\n    [<span class="str">\'name\'</span><span class="op">=&gt;</span><span class="str">\'Alice\'</span>, <span class="str">\'grades\'</span><span class="op">=&gt;</span>[<span class="num">90</span>,<span class="num">85</span>,<span class="num">92</span>]],\n    [<span class="str">\'name\'</span><span class="op">=&gt;</span><span class="str">\'Bob\'</span>, <span class="str">\'grades\'</span><span class="op">=&gt;</span>[<span class="num">78</span>,<span class="num">82</span>,<span class="num">88</span>]],\n];\n\n<span class="kw">foreach</span> (<span class="var">$students</span> <span class="kw">as</span> <span class="var">$s</span>) {\n    <span class="var">$avg</span> <span class="op">=</span> <span class="fn">array_sum</span>(<span class="var">$s</span>[<span class="str">\'grades\'</span>])\n        <span class="op">/</span> <span class="fn">count</span>(<span class="var">$s</span>[<span class="str">\'grades\'</span>]);\n    <span class="kw">echo</span> <span class="str">"</span><span class="var">$s[\'name\']</span><span class="str">: </span><span class="var">$avg</span><span class="str">&lt;br&gt;"</span>;\n}\n<span class="kw">echo</span> <span class="var">$students</span>[<span class="num">0</span>][<span class="str">\'grades\'</span>][<span class="num">1</span>]; <span class="cmt">// 85</span>','useCases'=>['Database result sets','Table/grid data','Nested configuration','Matrix operations'],'mistakes'=>['Deep nesting beyond 3 levels','Not initializing parent arrays','Off-by-one in nested loops'],['tips'=>['Keep nesting to 2-3 levels','Use foreach for clean iteration','Consider objects for deep data'],'interview'=>['How to access nested values?','How to flatten?','Nested arrays vs objects?']],
['name'=>'Array Functions','brief'=>'Built-in array utilities','explanation':'PHP has 70+ array functions. Key: array_push/pop, array_merge, array_map, array_filter, array_reduce, in_array, array_search.','syntax'=>'<span class="fn">array_push</span>(<span class="var">$a</span>, <span class="var">$v</span>);\n<span class="fn">array_pop</span>(<span class="var">$a</span>);\n<span class="fn">array_merge</span>(<span class="var">$a1</span>, <span class="var">$a2</span>);\n<span class="fn">array_map</span>(<span class="kw">fn</span>(<span class="var">$x</span>) <span class="op">=&gt;</span> <span class="var">$x</span> <span class="op">*</span> <span class="num">2</span>, <span class="var">$a</span>);\n<span class="fn">array_filter</span>(<span class="var">$a</span>, <span class="kw">fn</span>(<span class="var">$x</span>) <span class="op">=&gt;</span> <span class="var">$x</span> <span class="op">&gt;</span> <span class="num">5</span>);\n<span class="fn">in_array</span>(<span class="var">$v</span>, <span class="var">$a</span>);','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$nums</span> <span class="op">=</span> [<span class="num">1</span>, <span class="num">2</span>, <span class="num">3</span>, <span class="num">4</span>, <span class="num">5</span>];\n\n<span class="cmt">// Map: double each</span>\n<span class="var">$doubled</span> <span class="op">=</span> <span class="fn">array_map</span>(\n    <span class="kw">fn</span>(<span class="var">$n</span>) <span class="op">=&gt;</span> <span class="var">$n</span> <span class="op">*</span> <span class="num">2</span>, <span class="var">$nums</span>\n);\n\n<span class="cmt">// Filter: keep evens</span>\n<span class="var">$evens</span> <span class="op">=</span> <span class="fn">array_filter</span>(\n    <span class="var">$nums</span>, <span class="kw">fn</span>(<span class="var">$n</span>) <span class="op">=&gt;</span> <span class="var">$n</span> <span class="op">%</span> <span class="num">2</span> <span class="op">==</span> <span class="num">0</span>\n);\n\n<span class="cmt">// Reduce: sum</span>\n<span class="var">$sum</span> <span class="op">=</span> <span class="fn">array_reduce</span>(\n    <span class="var">$nums</span>, <span class="kw">fn</span>(<span class="var">$a</span>,<span class="var">$b</span>) <span class="op">=&gt;</span> <span class="var">$a</span><span class="op">+</span><span class="var">$b</span>, <span class="num">0</span>\n);\n\n<span class="kw">echo</span> <span class="fn">implode</span>(<span class="str">', '</span>, <span class="var">$doubled</span>);\n<span class="cmt">// 2, 4, 6, 8, 10</span>','useCases'=>['Transforming with array_map','Filtering with array_filter','Summing with array_reduce','Searching with in_array'],'mistakes'=>['Not preserving keys with map','array_merge re-indexes indexed arrays','array_filter preserves keys'],['tips'=>['Use fn() arrow functions','array_column to extract key','array_combine for keys+values'],'interview'=>['array_map vs array_walk?','Remove duplicates?','array_merge vs + operator?']],
['name'=>'Sorting Arrays','brief'=>'Sort, rsort, asort, ksort','explanation':'sort/rsort sort by value (re-indexes). asort/arsort sort by value (preserves keys). ksort/krsort sort by key. usort for custom.','syntax'=>'<span class="fn">sort</span>(<span class="var">$a</span>);      <span class="cmt">// value asc</span>\n<span class="fn">rsort</span>(<span class="var">$a</span>);     <span class="cmt">// value desc</span>\n<span class="fn">asort</span>(<span class="var">$a</span>);     <span class="cmt">// value asc + keys</span>\n<span class="fn">arsort</span>(<span class="var">$a</span>);    <span class="cmt">// value desc + keys</span>\n<span class="fn">ksort</span>(<span class="var">$a</span>);     <span class="cmt">// key asc</span>\n<span class="fn">usort</span>(<span class="var">$a</span>, <span class="kw">fn</span>(<span class="var">$a</span>,<span class="var">$b</span>) <span class="op">=&gt;</span> <span class="var">$a</span><span class="op">&lt;=&gt;</span><span class="var">$b</span>);','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="var">$nums</span> <span class="op">=</span> [<span class="num">5</span>, <span class="num">2</span>, <span class="num">8</span>, <span class="num">1</span>, <span class="num">9</span>];\n<span class="fn">sort</span>(<span class="var">$nums</span>);\n<span class="fn">print_r</span>(<span class="var">$nums</span>);\n<span class="cmt">// [1, 2, 5, 8, 9]</span>\n\n<span class="var">$scores</span> <span class="op">=</span> [<span class="str">\'Alice\'</span><span class="op">=&gt;</span><span class="num">95</span>, <span class="str">\'Bob\'</span><span class="op">=&gt;</span><span class="num">87</span>];\n<span class="fn">asort</span>(<span class="var">$scores</span>);\n<span class="fn">print_r</span>(<span class="var">$scores</span>);\n<span class="cmt">// Bob:87, Alice:95</span>\n\n<span class="cmt">// Custom sort</span>\n<span class="var">$items</span> <span class="op">=</span> [<span class="num">5</span>, <span class="num">2</span>, <span class="num">8</span>, <span class="num">1</span>];\n<span class="fn">usort</span>(<span class="var">$items</span>, <span class="kw">fn</span>(<span class="var">$a</span>,<span class="var">$b</span>) <span class="op">=&gt;</span> <span class="var">$a</span> <span class="op">&lt;=&gt;</span> <span class="var">$b</span>);\n\n<span class="fn">arsort</span>(<span class="var">$scores</span>);\n<span class="fn">print_r</span>(<span class="var">$scores</span>);\n<span class="cmt">// Alice:95, Bob:87</span>','useCases'=>['Displaying sorted data','Ranking and ordering','Priority queue','Alphabetical listing'],'mistakes'=>['sort() re-indexes (loses assoc)','usort modifies original','Not all sort functions return array'],'tips'=>['asort/arsort for assoc arrays','spaceship (<=>) for custom sorts','sort() returns bool not array'],'interview'=>['sort vs asort?','Sort assoc by value?','Custom comparison sorting?']]
]
