'id'=>'oop','name'=>'OOP','icon'=>'🏗️','color'=>'#eab308',
'subs'=>[
['name'=>'Class & Object','brief'=>'Classes, objects, properties, methods','explanation':'Classes are blueprints; objects are instances. Properties store data; methods define behavior. Constructor (__construct) initializes objects. PHP 8.0+ supports constructor property promotion.','syntax'=>'<span class="kw">class</span> <span class="fn">User</span> {\n    <span class="kw">public</span> <span class="var">string</span> <span class="var">$name</span>;\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(<span class="var">string</span> <span class="var">$name</span>) {\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">name</span> <span class="op">=</span> <span class="var">$name</span>;\n    }\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">greet</span>(): <span class="var">string</span> {\n        <span class="kw">return</span> <span class="str">"Hi, I\'m </span><span class="var">{$this-&gt;name}</span><span class="str">"</span>;\n    }\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">class</span> <span class="fn">Product</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(\n        <span class="kw">public</span> <span class="var">string</span> <span class="var">$name</span>,\n        <span class="kw">public</span> <span class="kw">float</span> <span class="var">$price</span>,\n        <span class="kw">private</span> <span class="kw">int</span> <span class="var">$stock</span> <span class="op">=</span> <span class="num">0</span>\n    ) {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">getInfo</span>(): <span class="var">string</span> {\n        <span class="kw">return</span> <span class="str">"</span><span class="var">{$this-&gt;name}</span><span class="str">: \$</span><span class="var">{$this-&gt;price}</span><span class="str">"</span>;\n    }\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">isAvailable</span>(): <span class="kw">bool</span> {\n        <span class="kw">return</span> <span class="var">$this</span><span class="op">-&gt;</span><span class="var">stock</span> <span class="op">&gt;</span> <span class="num">0</span>;\n    }\n}\n<span class="var">$p</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">Product</span>(<span class="str">\'Laptop\'</span>, <span class="num">999.99</span>, <span class="num">5</span>);\n<span class="kw">echo</span> <span class="var">$p</span><span class="op">-&gt;</span><span class="fn">getInfo</span>();','useCases'=>['Modeling real-world entities','Building application architecture','Creating reusable components','Encapsulating business logic'],['mistakes'=>['Overusing public properties','Not using type declarations','God classes doing too much'],['tips'=>['Use constructor property promotion','Keep classes small','Favor composition over inheritance'],'interview'=>['What is encapsulation?','PHP 8 constructor promotion?','Properties vs methods?']],
['name'=>'Access Modifiers','brief'=>'public, private, protected','explanation':'public: accessible everywhere. protected: class + subclasses. private: class only. Controls encapsulation and prevents external modification of internal state.','syntax'=>'<span class="kw">class</span> <span class="fn">Bank</span> {\n    <span class="kw">public</span> <span class="kw">float</span> <span class="var">$balance</span>;\n    <span class="kw">protected</span> <span class="var">string</span> <span class="var">$pin</span>;\n    <span class="kw">private</span> <span class="var">string</span> <span class="var">$password</span>;\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">class</span> <span class="fn">User</span> {\n    <span class="kw">public</span> <span class="var">string</span> <span class="var">$name</span>;\n    <span class="kw">protected</span> <span class="var">string</span> <span class="var">$email</span>;\n    <span class="kw">private</span> <span class="var">string</span> <span class="var">$password</span>;\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(<span class="var">string</span> <span class="var">$n</span>, <span class="var">string</span> <span class="var">$e</span>, <span class="var">string</span> <span class="var">$p</span>) {\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">name</span> <span class="op">=</span> <span class="var">$n</span>;\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">email</span> <span class="op">=</span> <span class="var">$e</span>;\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">password</span> <span class="op">=</span> <span class="var">$p</span>;\n    }\n}\n<span class="var">$u</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">User</span>(<span class="str">\'A\'</span>,<span class="str">\'a@b\'</span>,<span class="str">\'pass\'</span>);\n<span class="kw">echo</span> <span class="var">$u</span><span class="op">-&gt;</span><span class="var">name</span>;  <span class="cmt">// OK (public)</span>\n<span class="cmt">// echo $u->email;  // Error (protected)</span>\n<span class="cmt">// echo $u->password; // Error (private)</span>','useCases'=>['Hiding internal state','Controlling object access','API design boundaries','Security through encapsulation'],['mistakes'=>['Making everything public','Not using type hints','Exposing internal state'],['tips'=>['Default to private','Use protected for extensions','Public API should be minimal'],'interview'=>['public vs private vs protected?','Why use access modifiers?','protected vs private?']],
['name'=>'Inheritance','brief'=>'extends, parent, override','explanation':'Inheritance lets classes share code through parent-child relationships. Child classes extend parents and override methods. Use parent:: to call parent methods. PHP supports single inheritance only.','syntax'=>'<span class="kw">class</span> <span class="fn">Animal</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">speak</span>(): <span class="var">string</span> { <span class="kw">return</span> <span class="str">"..."</span>; }\n}\n<span class="kw">class</span> <span class="fn">Dog</span> <span class="kw">extends</span> <span class="fn">Animal</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">speak</span>(): <span class="var">string</span> { <span class="kw">return</span> <span class="str">"Woof!"</span>; }\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">class</span> <span class="fn">Shape</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(<span class="kw">protected</span> <span class="kw">float</span> <span class="var">$x</span>, <span class="kw">protected</span> <span class="kw">float</span> <span class="var">$y</span>) {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">area</span>(): <span class="kw">float</span> { <span class="kw">return</span> <span class="num">0</span>; }\n}\n<span class="kw">class</span> <span class="fn">Circle</span> <span class="kw">extends</span> <span class="fn">Shape</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(<span class="kw">float</span> <span class="var">$x</span>, <span class="kw">float</span> <span class="var">$y</span>, <span class="kw">private</span> <span class="kw">float</span> <span class="var">$r</span>) {\n        <span class="kw">parent</span>::<span class="fn">__construct</span>(<span class="var">$x</span>, <span class="var">$y</span>);\n    }\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">area</span>(): <span class="kw">float</span> {\n        <span class="kw">return</span> <span class="fn">M_PI</span> <span class="op">*</span> <span class="var">$this</span><span class="op">-&gt;</span><span class="var">$r</span> <span class="op">**</span> <span class="num">2</span>;\n    }\n}\n<span class="var">$c</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">Circle</span>(<span class="num">0</span>,<span class="num">0</span>,<span class="num">5</span>);\n<span class="kw">echo</span> <span class="var">$c</span><span class="op">-&gt;</span><span class="fn">area</span>(); <span class="cmt">// 78.54</span>','useCases'=>['Code reuse','Polymorphic interfaces','Template method pattern','Class hierarchies'],['mistakes'=>['Deep inheritance chains','Overriding without parent::','Not following LSP'],['tips'=>['Keep inheritance shallow','Use parent:: when overriding','Prefer composition'],'interview'=>['Single vs multiple inheritance?','When to use inheritance?','abstract vs interface?']],
['name'=>'Interfaces & Traits','brief'=>'Contracts and reusable code','explanation':'Interfaces define contracts a class must implement. Traits provide reusable code for multiple inheritance. Classes can implement multiple interfaces and use multiple traits.','syntax'=>'<span class="kw">interface</span> <span class="fn">Logger</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">log</span>(<span class="var">string</span> <span class="var">$msg</span>): <span class="var">void</span>;\n}\n<span class="kw">trait</span> <span class="fn">Timestampable</span> {\n    <span class="kw">public</span> <span class="var">string</span> <span class="var">$created_at</span>;\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">setTimestamp</span>(): <span class="var">void</span> {\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">created_at</span> <span class="op">=</span> <span class="fn">date</span>(<span class="str">\'Y-m-d H:i:s\'</span>);\n    }\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">interface</span> <span class="fn">HasEmail</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">getEmail</span>(): <span class="var">string</span>;\n}\n<span class="kw">trait</span> <span class="fn">SoftDelete</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">softDelete</span>(): <span class="var">void</span> {\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">deleted_at</span> <span class="op">=</span> <span class="fn">date</span>(<span class="str">\'Y-m-d\'</span>);\n    }\n}\n<span class="kw">class</span> <span class="fn">User</span> <span class="kw">implements</span> <span class="fn">HasEmail</span> {\n    <span class="kw">use</span> <span class="fn">SoftDelete</span>;\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(<span class="kw">private</span> <span class="var">string</span> <span class="var">$email</span>) {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">getEmail</span>(): <span class="var">string</span> {\n        <span class="kw">return</span> <span class="var">$this</span><span class="op">-&gt;</span><span class="var">email</span>;\n    }\n}',['useCases'=>['Defining contracts','Code reuse without inheritance','Decoupling implementations','Plugin systems'],['mistakes'=>['Using traits when interfaces suffice','Diamond problem with traits','Too many traits'],['tips'=>['Prefer interfaces for contracts','Traits for cross-cutting concerns','Keep traits focused'],'interview'=>['Interface vs abstract class?','How do traits work?','Multiple traits?']],
['name'=>'Magic Methods','brief'=>'__construct, __get, __toString, etc.','explanation':'Magic methods are triggered by specific PHP actions. __construct for init, __get/__set for property access, __toString for string conversion, __call for method calls, __invoke for callable objects.','syntax'=>'<span class="kw">class</span> <span class="fn">Magic</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>() {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__get</span>(<span class="var">$n</span>) {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__set</span>(<span class="var">$n</span>,<span class="var">$v</span>) {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__toString</span>(): <span class="var">string</span> {}\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__call</span>(<span class="var">$n</span>,<span class="var">$a</span>) {}\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">class</span> <span class="fn">Config</span> {\n    <span class="kw">private</span> <span class="var">array</span> <span class="var">$data</span> <span class="op">=</span> [];\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__get</span>(<span class="var">string</span> <span class="var">$k</span>): <span class="var">mixed</span> {\n        <span class="kw">return</span> <span class="var">$this</span><span class="op">-&gt;</span><span class="var">$data</span>[<span class="var">$k</span>] <span class="op">??</span> <span class="kw">null</span>;\n    }\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__set</span>(<span class="var">string</span> <span class="var">$k</span>, <span class="var">mixed</span> <span class="var">$v</span>): <span class="var">void</span> {\n        <span class="var">$this</span><span class="op">-&gt;</span><span class="var">$data</span>[<span class="var">$k</span>] <span class="op">=</span> <span class="var">$v</span>;\n    }\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__toString</span>(): <span class="var">string</span> {\n        <span class="kw">return</span> <span class="fn">json_encode</span>(<span class="var">$this</span><span class="op">-&gt;</span><span class="var">$data</span>);\n    }\n}\n<span class="var">$c</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">Config</span>();\n<span class="var">$c</span><span class="op">-&gt;</span><span class="var">name</span> <span class="op">=</span> <span class="str">"Alice"</span>;\n<span class="kw">echo</span> <span class="var">$c</span><span class="op">-&gt;</span><span class="var">name</span>;\n<span class="kw">echo</span> <span class="var">$c</span>; <span class="cmt">// {"name":"Alice"}</span>','useCases'=>['Dynamic property access','Object serialization','Proxy patterns','Flexible APIs'],['mistakes'=>['Overusing __get/__set','Not handling __call','Performance impact'],['tips'=>['Use __get/__set for dynamic props','__toString for debugging','__call for flexible methods'],'interview'=>['What are magic methods?','When to use __get/__set?','__toString purpose?']]
]
];
