'id'=>'security','name'=>'Security','icon'=>'🛡️','color'=>'#dc2626',
'subs'=>[
['name'=>'SQL Injection','brief'=>'Preventing database attacks','explanation':'SQL injection occurs when user input is inserted directly into SQL queries. Attackers can manipulate queries to access, modify, or delete data. Always use prepared statements with parameterized queries to prevent this.','syntax'=>'<span class="cmt">// DANGEROUS</span>\n<span class="var">$db</span><span class="op">-&gt;</span><span class="fn">query</span>(<span class="str">"SELECT * FROM users WHERE id=</span><span class="var">$id</span><span class="str">"</span>);\n\n<span class="cmt">// SAFE - Prepared statement</span>\n<span class="var">$stmt</span> <span class="op">=</span> <span class="var">$pdo</span><span class="op">-&gt;</span><span class="fn">prepare</span>(<span class="str">"SELECT * FROM users WHERE id=:id"</span>);\n<span class="var">$stmt</span><span class="op">-&gt;</span><span class="fn">execute</span>([<span class="str">\'id\'</span> <span class="op">=&gt;</span> <span class="var">$id</span>]);','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Input from user</span>\n<span class="var">$id</span> <span class="op">=</span> <span class="var">$_GET</span>[<span class="str">\'id\'</span>];\n\n<span class="cmt">// ATTACK: id = "1 OR 1=1; DROP TABLE users;"</span>\n<span class="cmt">// $db->query("SELECT * FROM users WHERE id=$id");</span>\n\n<span class="cmt">// DEFENSE: Prepared statement</span>\n<span class="var">$stmt</span> <span class="op">=</span> <span class="var">$pdo</span><span class="op">-&gt;</span><span class="fn">prepare</span>(\n    <span class="str">"SELECT * FROM users WHERE id = :id"</span>\n);\n<span class="var">$stmt</span><span class="op">-&gt;</span><span class="fn">execute</span>([<span class="str">\'id\'</span> <span class="op">=&gt;</span> <span class="var">$id</span>]);\n<span class="var">$user</span> <span class="op">=</span> <span class="var">$stmt</span><span class="op">-&gt;</span><span class="fn">fetch</span>();','useCases'=>['All database queries','User input handling','Search functionality','API endpoints'],['mistakes'=>['String concatenation in queries','Trusting user input','Not using prepared statements'],['tips'=>['Always use prepared statements','Validate input types before queries','Use stored procedures for complex ops'],'interview'=>['What is SQL injection?','How do prepared statements prevent it?','Stored procedures vs prepared statements?']],
['name'=>'XSS Prevention','brief'=>'Cross-Site Scripting defense','explanation':'XSS attacks inject malicious scripts into web pages viewed by others. Prevent by escaping all output with htmlspecialchars(), using Content Security Policy headers, and validating/sanitizing user input.','syntax'=>'<span class="cmt">// ESCAPE OUTPUT</span>\n<span class="fn">htmlspecialchars</span>(<span class="var">$userInput</span>, <span class="const">ENT_QUOTES</span>, <span class="str">\'UTF-8\'</span>);\n\n<span class="cmt">// Content Security Policy header</span>\n<span class="fn">header</span>(<span class="str">"Content-Security-Policy: default-src \'self\'"</span>);','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// DANGEROUS - XSS vulnerability</span>\n<span class="kw">echo</span> <span class="str">"Hello, </span><span class="var">$_GET[\'name\']</span><span class="str">!"</span>;\n<span class="cmt">// Attacker: ?name=&lt;script&gt;steal_cookies()&lt;/script&gt;</span>\n\n<span class="cmt">// SAFE - Escaped output</span>\n<span class="var">$name</span> <span class="op">=</span> <span class="fn">htmlspecialchars</span>(\n    <span class="var">$_GET</span>[<span class="str">\'name\'</span>] <span class="op">??</span> <span class="str">\'Guest\'</span>,\n    <span class="const">ENT_QUOTES</span>,\n    <span class="str">\'UTF-8\'</span>\n);\n<span class="kw">echo</span> <span class="str">"Hello, </span><span class="var">$name</span><span class="str">!"</span>;\n\n<span class="cmt">// CSP Header</span>\n<span class="fn">header</span>(<span class="str">"Content-Security-Policy: default-src \'self\'"</span>);\n\n<span class="cmt">// JSON response safe</span>\n<span class="fn">header</span>(<span class="str">\'Content-Type: application/json; charset=utf-8\'</span>);\n<span class="kw">echo</span> <span class="fn">json_encode</span>([<span class="str">\'msg\'</span> <span class="op">=&gt;</span> <span class="var">$name</span>]);','useCases'=>['Dynamic HTML output','User-generated content display','API responses','Email templates'],['mistakes'=>['Forgetting htmlspecialchars on output','Using echo with user data','Not setting charset header'],['tips'=>['Escape ALL output with htmlspecialchars','Set Content-Security-Policy headers','Use textContent instead of innerHTML in JS'],'interview'=>['What is XSS?','How to prevent reflected XSS?','CSP headers explained?']],
['name'=>'CSRF Defense','brief'=>'Cross-Site Request Forgery protection','explanation':'CSRF tricks users into submitting unwanted forms. Protection uses unique tokens embedded in forms and verified on submission. Each session gets a token that must match on state-changing requests.','syntax'=>'<span class="cmt">// Generate token</span>\nsession_start();\n<span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>] <span class="op">=</span> <span class="fn">bin2hex</span>(<span class="fn">random_bytes</span>(<span class="num">32</span>));\n\n<span class="cmt">// In form</span>\n<span class="cmt">// &lt;input type="hidden" name="csrf" value="</span><span class="op">&lt;?=</span> <span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>] <span class="op">?&gt;</span><span class="cmt">"&gt;</span>\n\n<span class="cmt">// Verify on submit</span>\n<span class="kw">if</span> (<span class="var">$_POST</span>[<span class="str">\'csrf\'</span>] <span class="op">!==</span> <span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>]) {\n    <span class="kw">die</span>(<span class="str">"Invalid token"</span>);\n}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\nsession_start();\n\n<span class="kw">function</span> <span class="fn">csrfToken</span>(): <span class="var">string</span> {\n    <span class="kw">if</span> (<span class="op">!</span><span class="fn">isset</span>(<span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>])) {\n        <span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>] <span class="op">=</span> <span class="fn">bin2hex</span>(<span class="fn">random_bytes</span>(<span class="num">32</span>));\n    }\n    <span class="kw">return</span> <span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>];\n}\n<span class="kw">function</span> <span class="fn">verifyCsrf</span>(): <span class="var">bool</span> {\n    <span class="kw">return</span> (<span class="var">$_POST</span>[<span class="str">\'csrf\'</span>] <span class="op">??</span> <span class="str">\'\'</span>) <span class="op">===</span> (<span class="var">$_SESSION</span>[<span class="str">\'csrf\'</span>] <span class="op">??</span> <span class="str">\'\'</span>);\n}\n<span class="kw">echo</span> <span class="str">"&lt;input type=\'hidden\' name=\'csrf\' value=\'"</span> <span class="op">.</span> <span class="fn">csrfToken</span>() <span class="op">.</span> <span class="str">"\'&gt;"</span>;\n<span class="kw">if</span> (<span class="op">!</span><span class="fn">verifyCsrf</span>()) <span class="kw">die</span>(<span class="str">"CSRF invalid"</span>);','useCases'=>['Protecting form submissions','Securing AJAX requests','State change protection','Guarding against malicious links'],['mistakes'=>['No CSRF on state-changing requests','Regenerating token every request','Token in cookie instead of session'],['tips'=>['Use bin2hex(random_bytes(32))','Verify on every POST/PUT/DELETE','Store token in session'],'interview'=>['What is CSRF?','How do tokens work?','Why random_bytes()?']],
['name'=>'Password Hashing','brief'=>'Secure password storage','explanation':'Never store passwords in plain text. Use password_hash() with PASSWORD_DEFAULT (bcrypt/Argon2). password_verify() checks passwords against hashes. password_needs_rehash() detects outdated algorithms.','syntax'=>'<span class="cmt">// Hash</span>\n<span class="var">$hash</span> <span class="op">=</span> <span class="fn">password_hash</span>(<span class="var">$pass</span>, <span class="const">PASSWORD_DEFAULT</span>);\n\n<span class="cmt">// Verify</span>\n<span class="fn">password_verify</span>(<span class="var">$input</span>, <span class="var">$hash</span>);\n\n<span class="cmt">// Rehash if needed</span>\n<span class="kw">if</span> (<span class="fn">password_needs_rehash</span>(<span class="var">$hash</span>, <span class="const">PASSWORD_DEFAULT</span>)) {\n    <span class="var">$hash</span> <span class="op">=</span> <span class="fn">password_hash</span>(<span class="var">$pass</span>, <span class="const">PASSWORD_DEFAULT</span>);\n}','codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Registration</span>\n<span class="var">$pass</span> <span class="op">=</span> <span class="var">$_POST</span>[<span class="str">\'password\'</span>];\n<span class="var">$hash</span> <span class="op">=</span> <span class="fn">password_hash</span>(<span class="var">$pass</span>, <span class="const">PASSWORD_DEFAULT</span>);\n<span class="cmt">// Store $hash in database</span>\n\n<span class="cmt">// Login verification</span>\n<span class="var">$input</span> <span class="op">=</span> <span class="var">$_POST</span>[<span class="str">\'password\'</span>];\n<span class="var">$dbHash</span> <span class="op">=</span> <span class="cmt">/* from DB */</span>;\n\n<span class="kw">if</span> (<span class="fn">password_verify</span>(<span class="var">$input</span>, <span class="var">$dbHash</span>)) {\n    <span class="kw">echo</span> <span class="str">"Login successful!"</span>;\n    <span class="fn">session_start</span>();\n    <span class="var">$_SESSION</span>[<span class="str">\'user_id\'</span>] <span class="op">=</span> <span class="cmt">/* id */</span>;\n} <span class="kw">else</span> {\n    <span class="kw">echo</span> <span class="str">"Invalid credentials"</span>;\n}\n\n<span class="cmt">// Check if rehash needed</span>\n<span class="kw">if</span> (<span class="fn">password_needs_rehash</span>(<span class="var">$dbHash</span>, <span class="const">PASSWORD_DEFAULT</span>)) {\n    <span class="var">$newHash</span> <span class="op">=</span> <span class="fn">password_hash</span>(<span class="var">$input</span>, <span class="const">PASSWORD_DEFAULT</span>);\n    <span class="cmt">// Update in DB</span>\n}','useCases'=>['User registration','Login authentication','Password reset flows','API key storage'],['mistakes'=>['Storing plain text passwords','Using md5/sha1 for passwords','Not using salt (password_hash handles it)'],['tips'=>['Always use password_hash/verify','Never log plain text passwords','Use PASSWORD_DEFAULT for auto-upgrade'],['interview'=>['Why not md5 for passwords?','How does password_hash work?','What is bcrypt?']]
]
];
