'id'=>'composer','name'=>'Composer','icon'=>'📦','color'=>'#8b5cf6',
'subs'=>[
['name'=>'Installation','brief'=>'Setting up Composer','explanation':'Composer is PHP dependency manager. Install globally or per-project. Download from getcomposer.org. Run the installer and add composer to your PATH. Verify with composer --version.','syntax'=>'<span class="cmt"># Install Composer globally</span>\ncurl -sS https://getcomposer.org/installer | php\nsudo mv composer.phar /usr/local/bin/composer\n\n<span class="cmt"># Verify</span>\ncomposer --version','codeExample'=>'<span class="cmt"># Install Composer on Windows</span>\n<span class="cmt"># Download installer from getcomposer.org</span>\n<span class="cmt"># Run Composer-Setup.exe</span>\n\n<span class="cmt"># Verify installation</span>\ncomposer --version\n<span class="cmt"># Composer version 2.x.x</span>\n\n<span class="cmt"># Create new project</span>\ncomposer create-project laravel/laravel myapp\n\n<span class="cmt"># Initialize in existing project</span>\ncomposer init','useCases'=>['Dependency management','Project scaffolding','Autoloading classes','Build automation'],['mistakes'=>['Not committing composer.lock','Using composer install in production','Global instead of local packages'],['tips'=>['Commit composer.lock to git','Use composer update to upgrade','Install dev dependencies only locally'],'interview'=>['What is Composer?','composer install vs update?','Why commit composer.lock?']],
['name'=>'composer.json','brief':'Package configuration file','explanation':'composer.json defines your project metadata, dependencies, and autoloading. It is the equivalent of package.json in Node.js. Declares required packages with version constraints and scripts for automation.','syntax'=>'{\n    "name": "vendor/package",\n    "require": {\n        "php": ">=8.1",\n        "monolog/monolog": "^3.0"\n    },\n    "require-dev": {\n        "phpunit/phpunit": "^10.0"\n    },\n    "autoload": {\n        "psr-4": {\n            "App\\\\": "src/"\n        }\n    }\n}','codeExample'=>'{\n    "name": "mycompany/myapp",\n    "description": "My PHP application",\n    "type": "project",\n    "license": "MIT",\n    "require": {\n        "php": ">=8.1",\n        "guzzlehttp/guzzle": "^7.8",\n        "monolog/monolog": "^3.5"\n    },\n    "require-dev": {\n        "phpunit/phpunit": "^10.5",\n        "phpstan/phpstan": "^1.10"\n    },\n    "autoload": {\n        "psr-4": {\n            "App\\\\": "src/"\n        }\n    },\n    "scripts": {\n        "test": "phpunit",\n        "lint": "phpstan analyse"\n    }\n}','useCases'=>['Defining project dependencies','Configuring autoloading','Setting up dev tools','Defining scripts/tasks'],['mistakes'=>['Confusing require vs require-dev','Not specifying version constraints','Forgetting autoload configuration'],['tips'=>['Use ^ for minor version flexibility','Pin exact versions for critical deps','Use scripts for common tasks'],'interview'=>['require vs require-dev?','Semantic versioning explained?','What goes in autoload?']],
['name'=>'PSR-4 Autoloading','brief'=>'Standard class loading','explanation':'PSR-4 is the PHP autoloading standard. Maps namespaces to directory structures. When a class is used, Composer automatically finds and loads the correct file. No more require/include statements for classes.','syntax'=>'<span class="cmt">// composer.json</span>\n"autoload": {\n    "psr-4": {\n        "App\\\\": "src/"\n    }\n}\n\n<span class="cmt">// src/User.php</span>\nnamespace App;\n\nclass User {\n    // ...\n}\n\n<span class="cmt">// Automatically loaded!</span>\n$user = new App\\User();','codeExample'=>'<span class="cmt">// Directory structure</span>\n<span class="cmt">// src/</span>\n<span class="cmt">//   Controller/</span>\n<span class="cmt">//     HomeController.php</span>\n<span class="cmt">//   Model/</span>\n<span class="cmt">//     User.php</span>\n<span class="cmt">//   Service/</span>\n<span class="cmt">//     MailService.php</span>\n\n<span class="cmt">// src/Model/User.php</span>\nnamespace App\\Model;\n\nclass User {\n    public function __construct(\n        private string $name\n    ) {}\n}\n\n<span class="cmt">// src/Controller/HomeController.php</span>\nnamespace App\\Controller;\nuse App\\Model\\User;\n\nclass HomeController {\n    public function index() {\n        $user = new User(\'Alice\');\n        // Class auto-loaded by Composer!\n    }\n}',['useCases'=>['Automatic class loading','Following PHP-FIG standards','Framework development','Library distribution'],['mistakes'=>['Wrong namespace/directory mapping','Not running composer dump-autoload','Mixing PSR-4 with classmap'],['tips'=>['Follow PSR-4 strictly','One class per file','Run dump-autoload after changes'],'interview'=>['What is PSR-4?','How does autoloading work?','PSR-4 vs classmap?']]
]
];

$topics[] = [
'id'=>'mvc','name'=>'MVC','icon'=>'🏛️','color'=>'#06b6d4',
'subs'=>[
['name'=>'Model','brief'=>'Data and business logic layer','explanation':'The Model represents data and business logic. It handles database operations, validation, and domain rules. Models are independent of presentation and should not contain HTML or display logic.','syntax'=>'<span class="kw">class</span> <span class="fn">User</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(\n        <span class="kw">private</span> <span class="var">int</span> <span class="var">$id</span>,\n        <span class="kw">private</span> <span class="var">string</span> <span class="var">$name</span>,\n        <span class="kw">private</span> <span class="var">string</span> <span class="var">$email</span>\n    ) {}\n\n    <span class="kw">public</span> <span class="kw">static</span> <span class="kw">function</span> <span class="fn">find</span>(<span class="var">int</span> <span class="var">$id</span>): <span class="op">?</span><span class="kw">self</span> {\n        <span class="cmt">// Database query</span>\n    }\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">save</span>(): <span class="var">bool</span> {\n        <span class="cmt">// Insert/update database</span>\n    }\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">namespace</span> App\\Model;\n\n<span class="kw">class</span> <span class="fn">User</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">__construct</span>(\n        <span class="kw">private</span> <span class="var">int</span> <span class="var">$id</span> <span class="op">=</span> <span class="num">0</span>,\n        <span class="kw">public</span> <span class="var">string</span> <span class="var">$name</span> <span class="op">=</span> <span class="str">\'\'</span>,\n        <span class="kw">public</span> <span class="var">string</span> <span class="var">$email</span> <span class="op">=</span> <span class="str">\'\'</span>\n    ) {}\n\n    <span class="kw">public</span> <span class="kw">static</span> <span class="kw">function</span> <span class="fn">find</span>(<span class="var">int</span> <span class="var">$id</span>): <span class="op">?</span><span class="kw">self</span> {\n        <span class="cmt">// DB query to find user</span>\n        <span class="kw">return new</span> <span class="kw">self</span>(<span class="var">$id</span>, <span class="str">\'Alice\'</span>, <span class="str">\'a@b.com\'</span>);\n    }\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">save</span>(): <span class="var">bool</span> {\n        <span class="cmt">// INSERT or UPDATE in DB</span>\n        <span class="kw">return</span> <span class="kw">true</span>;\n    }\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">toArray</span>(): <span class="var">array</span> {\n        <span class="kw">return</span> <span class="fn">get_object_vars</span>(<span class="var">$this</span>);\n    }\n}\n\n<span class="var">$user</span> <span class="op">=</span> <span class="fn">User</span>::<span class="fn">find</span>(<span class="num">1</span>);\n<span class="var">$user</span><span class="op">-&gt;</span><span class="var">name</span> <span class="op">=</span> <span class="str">\'Bob\'</span>;\n<span class="var">$user</span><span class="op">-&gt;</span><span class="fn">save</span>();','useCases'=>['Database CRUD operations','Business rule validation','Data transformation','Domain logic encapsulation'],['mistakes'=>['Adding HTML in models','Direct $_POST access in models','God models doing everything'],['tips'=>['Keep models focused on data','Use repositories for complex queries','Validate in models not controllers'],'interview'=>['Role of Model in MVC?','Fat model vs fat controller?','When to use repositories?']],
['name'=>'View','brief'=>'Presentation/template layer','explanation':'Views handle display logic and HTML output. They receive data from controllers and render the user interface. Views should contain minimal PHP logic, mainly for loops and conditionals to render data.','syntax'=>'<span class="cmt">// views/users/index.php</span>\n&lt;h1&gt;Users&lt;/h1&gt;\n&lt;ul&gt;\n<span class="op">&lt;?=</span> <span class="kw">foreach</span> (<span class="var">$users</span> <span class="kw">as</span> <span class="var">$user</span>): <span class="op">?&gt;</span>\n    &lt;li&gt;\n        <span class="op">&lt;?=</span> <span class="fn">htmlspecialchars</span>(<span class="var">$user</span><span class="op">-&gt;</span><span class="var">name</span>) <span class="op">?&gt;</span>\n    &lt;/li&gt;\n<span class="op">&lt;?=</span> <span class="kw">endforeach</span>; <span class="op">?&gt;</span>\n&lt;/ul&gt;","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span> <span class="cmt">// views/users/index.php</span> <span class="op">?&gt;</span>\n&lt;!DOCTYPE html&gt;\n&lt;html&gt;\n&lt;head&gt;&lt;title&gt;Users&lt;/title&gt;&lt;/head&gt;\n&lt;body&gt;\n&lt;h1&gt;User List&lt;/h1&gt;\n&lt;table&gt;\n    &lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;th&gt;Email&lt;/th&gt;&lt;/tr&gt;\n    <span class="op">&lt;?php foreach</span> (<span class="var">$users</span> <span class="kw">as</span> <span class="var">$user</span>): <span class="op">?&gt;</span>\n    &lt;tr&gt;\n        &lt;td&gt;<span class="op">&lt;?=</span> <span class="fn">htmlspecialchars</span>(<span class="var">$user</span>[<span class="str">\'name\'</span>]) <span class="op">?&gt;</span>&lt;/td&gt;\n        &lt;td&gt;<span class="op">&lt;?=</span> <span class="fn">htmlspecialchars</span>(<span class="var">$user</span>[<span class="str">\'email\'</span>]) <span class="op">?&gt;</span>&lt;/td&gt;\n    &lt;/tr&gt;\n    <span class="op">&lt;?php endforeach</span>; <span class="op">?&gt;</span>\n&lt;/table&gt;\n&lt;/body&gt;\n&lt;/html&gt;','useCases'=>['HTML page rendering','Email templates','PDF generation','AJAX response formatting'],['mistakes'=>['Database queries in views','Business logic in views','Not escaping output'],['tips'=>['Keep views simple','Always escape output','Use template inheritance'],'interview'=>['What belongs in a View?','How to escape output?','Template engines vs raw PHP?']],
['name'=>'Controller','brief'=>'Request handling layer','explanation':'Controllers handle HTTP requests, process input, call models, and select views. They act as intermediaries between models and views. Keep controllers thin with simple action methods.','syntax'=>'<span class="kw">class</span> <span class="fn">UserController</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">index</span>() {\n        <span class="var">$users</span> <span class="op">=</span> <span class="fn">User</span>::<span class="fn">all</span>();\n        <span class="fn">view</span>(<span class="str">\'users/index\'</span>, [<span class="str">\'users\'</span> <span class="op">=&gt;</span> <span class="var">$users</span>]);\n    }\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">store</span>() {\n        <span class="var">$user</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">User</span>();\n        <span class="var">$user</span><span class="op">-&gt;</span><span class="var">name</span> <span class="op">=</span> <span class="var">$_POST</span>[<span class="str">\'name\'</span>];\n        <span class="var">$user</span><span class="op">-&gt;</span><span class="fn">save</span>();\n        <span class="fn">redirect</span>(<span class="str">\'/users\'</span>);\n    }\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="kw">namespace</span> App\\Controller;\n\n<span class="kw">class</span> <span class="fn">UserController</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">index</span>() {\n        <span class="var">$users</span> <span class="op">=</span> <span class="fn">User</span>::<span class="fn">all</span>();\n        <span class="fn">require</span> <span class="str">\'views/users/index.php\'</span>;\n    }\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">show</span>(<span class="var">int</span> <span class="var">$id</span>) {\n        <span class="var">$user</span> <span class="op">=</span> <span class="fn">User</span>::<span class="fn">find</span>(<span class="var">$id</span>);\n        <span class="kw">if</span> (<span class="op">!</span><span class="var">$user</span>) <span class="fn">http_response_code</span>(<span class="num">404</span>);\n        <span class="fn">require</span> <span class="str">\'views/users/show.php\'</span>;\n    }\n\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">store</span>() {\n        <span class="fn">validate</span>(<span class="var">$_POST</span>, [<span class="str">\'name\'</span><span class="op">=&gt;</span><span class="str">\'required\'</span>]);\n        <span class="var">$user</span> <span class="op">=</span> <span class="kw">new</span> <span class="fn">User</span>();\n        <span class="var">$user</span><span class="op">-&gt;</span><span class="var">name</span> <span class="op">=</span> <span class="var">$_POST</span>[<span class="str">\'name\'</span>];\n        <span class="var">$user</span><span class="op">-&gt;</span><span class="fn">save</span>();\n        <span class="fn">header</span>(<span class="str">\'Location: /users\'</span>);\n    }\n}','useCases'=>['HTTP request routing','Input validation','Calling models','Selecting views'],['mistakes'=>['Fat controllers with too much logic','Direct database access in controllers','Not validating input'],['tips'=>['Keep controllers thin','Delegate business logic to models','One action per method'],'interview'=>['Role of Controller in MVC?','Fat model vs fat controller?','How to handle form submissions?']],
['name'=>'Routing','brief'=>'URL to controller mapping','explanation':'Routing maps URLs to controller actions. Define routes with HTTP method, URL pattern, and handler. Modern PHP frameworks use clean routing. You can also implement basic routing with a switch statement.','syntax'=>'<span class="cmt">// Basic routing</span>\n<span class="var">$uri</span> <span class="op">=</span> <span class="var">$_SERVER</span>[<span class="str">\'REQUEST_URI\'</span>];\n<span class="kw">switch</span> (<span class="var">$uri</span>) {\n    <span class="kw">case</span> <span class="str">\'/\'</span>:\n        <span class="kw">echo</span> <span class="str">"Home"</span>;\n        <span class="kw">break</span>;\n    <span class="kw">case</span> <span class="str">\'/about\'</span>:\n        <span class="kw">echo</span> <span class="str">"About"</span>;\n        <span class="kw">break</span>;\n}","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Simple router</span>\n<span class="var">$routes</span> <span class="op">=</span> [\n    <span class="str">\'GET /\'</span> <span class="op">=&gt;</span> [<span class="str">\'HomeController\'</span>, <span class="str">\'index\'</span>],\n    <span class="str">\'GET /users\'</span> <span class="op">=&gt;</span> [<span class="str">\'UserController\'</span>, <span class="str">\'index\'</span>],\n    <span class="str">\'GET /users/{id}\'</span> <span class="op">=&gt;</span> [<span class="str">\'UserController\'</span>, <span class="str">\'show\'</span>],\n    <span class="str">\'POST /users\'</span> <span class="op">=&gt;</span> [<span class="str">\'UserController\'</span>, <span class="str">\'store\'</span>],\n];\n\n<span class="var">$method</span> <span class="op">=</span> <span class="var">$_SERVER</span>[<span class="str">\'REQUEST_METHOD\'</span>];\n<span class="var">$uri</span> <span class="op">=</span> <span class="fn">parse_url</span>(<span class="var">$_SERVER</span>[<span class="str">\'REQUEST_URI\'</span>], <span class="const">PHP_URL_PATH</span>);\n<span class="var">$key</span> <span class="op">=</span> <span class="var">$method</span> <span class="op">.</span> <span class="str">\' \'</span> <span class="op">.</span> <span class="var">$uri</span>;\n\n<span class="kw">if</span> (<span class="fn">isset</span>(<span class="var">$routes</span>[<span class="var">$key</span>])) {\n    [<span class="var">$controller</span>, <span class="var">$action</span>] <span class="op">=</span> <span class="var">$routes</span>[<span class="var">$key</span>];\n    <span class="kw">echo</span> <span class="str">"Calling </span><span class="var">$controller</span><span class="str">::</span><span class="var">$action</span><span class="str">"</span>;\n} <span class="kw">else</span> {\n    <span class="fn">http_response_code</span>(<span class="num">404</span>);\n    <span class="kw">echo</span> <span class="str">"Not Found"</span>;\n}',['useCases'=>['URL mapping to controllers','RESTful API design','Clean URL handling','Middleware integration'],['mistakes'=>['Hardcoding URLs in views','Not handling 404 errors','No HTTP method differentiation'],['tips'=>['Use route parameters for IDs','Separate route definitions','Handle all HTTP methods'],'interview'=>['What is routing in MVC?','How do frameworks handle routes?','RESTful routing patterns?']],
['name'=>'Middleware','brief'=>'Request/response processing pipeline','explanation':'Middleware processes HTTP requests before they reach controllers and responses before they are sent. Common uses: authentication, logging, CORS, rate limiting. Middleware can modify or reject requests.','syntax'=>'<span class="cmt">// Middleware interface</span>\n<span class="kw">interface</span> <span class="fn">Middleware</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">handle</span>(\n        <span class="var">$request</span>,\n        <span class="kw">callable</span> <span class="var">$next</span>\n    ): <span class="var">mixed</span>;\n}\n\n<span class="cmt">// Usage</span>\n<span class="var">$app</span><span class="op">-&gt;</span><span class="fn">use</span>(<span class="kw">new</span> <span class="fn">AuthMiddleware</span>());\n<span class="var">$app</span><span class="op">-&gt;</span><span class="fn">use</span>(<span class="kw">new</span> <span class="fn">LogMiddleware</span>());","codeExample'=>'<span class="op">&lt;?</span><span class="kw">php</span>\n<span class="cmt">// Authentication middleware</span>\n<span class="kw">class</span> <span class="fn">AuthMiddleware</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">handle</span>(<span class="var">$req</span>, <span class="kw">callable</span> <span class="var">$next</span>): <span class="var">mixed</span> {\n        <span class="fn">session_start</span>();\n        <span class="kw">if</span> (<span class="op">!</span>(<span class="var">$_SESSION</span>[<span class="str">\'user_id\'</span>] <span class="op">??</span> <span class="kw">false</span>)) {\n            <span class="fn">header</span>(<span class="str">\'Location: /login\'</span>);\n            <span class="kw">exit</span>;\n        }\n        <span class="kw">return</span> <span class="var">$next</span>(<span class="var">$req</span>);\n    }\n}\n\n<span class="cmt">// Logging middleware</span>\n<span class="kw">class</span> <span class="fn">LogMiddleware</span> {\n    <span class="kw">public</span> <span class="kw">function</span> <span class="fn">handle</span>(<span class="var">$req</span>, <span class="kw">callable</span> <span class="var">$next</span>): <span class="var">mixed</span> {\n        <span class="var">$start</span> <span class="op">=</span> <span class="fn">microtime</span>(<span class="kw">true</span>);\n        <span class="var">$result</span> <span class="op">=</span> <span class="var">$next</span>(<span class="var">$req</span>);\n        <span class="var">$time</span> <span class="op">=</span> <span class="fn">microtime</span>(<span class="kw">true</span>) <span class="op">-</span> <span class="var">$start</span>;\n        <span class="fn">error_log</span>(<span class="str">"</span><span class="var">{$_SERVER[\'REQUEST_URI\']}</span><span class="str"> in </span><span class="var">$time</span><span class="str">s"</span>);\n        <span class="kw">return</span> <span class="var">$result</span>;\n    }\n}',['useCases'=>['Authentication checks','Request logging','CORS headers','Rate limiting','Input sanitization'],['mistakes'=>['Not calling $next()','Blocking response with slow middleware','Not handling errors in middleware'],['tips'=>['Keep middleware focused','Always call $next()','Order matters - first registered runs first'],'interview'=>['What is middleware?','Middleware vs decorator pattern?','How to implement authentication middleware?']]
]
];
